                    [0x6f48c5680a6578a8UL] = "¡Mueve tu culo!",
                    [0x6ffcc22b3a80afd2UL] = "¡Socorro! ¡Va a por mí!",
                    [0x7032c1ee00e8c277UL] = "Jeff",
                    [0x70818f5012b2a6b9UL] = "Vale, veamoh aquí. Preferiría mi fiel avión, pero... ehtoh servirá. Shi puedo encontrar el contacto. Ah, aquí ehtá.",
                    [0x70897260e656a02cUL] = "BLOQUE",
                    [0x72a8dd799de66b83UL] = "SALIDA",
                    [0x74d1004c33a4cf82UL] = "Ehta coha eh vieja incluho para mí... ¿Dónde va ehta pieza? No, ahsí no eh...",
                    [0x76593c4f11889014UL] = "Quiero decir, ¿qué shentido tiene shi pueden simplemente... hmm... umm... eh eho un...?",
                    [0x76bae89ee56047a0UL] = "¡Dios nos salve, es la Pandilla Colmena!",
                    [0x794b42e6e43d51acUL] = "Nel.",
                    [0x80dc943a46520f6cUL] = "¡Eh, jefe! ¡Quiero mi llamada!",
                    [0x87ee43f95113b100UL] = "MATAD\r\n  A TODOS\r\nLOS POLIS",
                    [0x8ac3573c90cfbc94UL] = "¿Así que pondrás a mis propios hombres en mi contra?! ¡Maldita, apestosa, sedienta de sangre...",
                    [0x8b374962aea1e30eUL] = "¡Ja! ¡Ni hablar!",
                    [0x8b3bc239dedf1bc0UL] = "¡Mierda, vienen! Escuchad. Hay un ascensor tras la puerta detrás de vosotros. Intentaré encontrar otro camino arriba. Nos vemos allí, eso espero.",
                    [0x8b3bd9f00d1c3605UL] = "¡No! ¿Cómo habéis entrado? ¡AYUDA!!",
                    [0x8b8b89dc8de8ecf6UL] = "Mátalos.",
                    [0x8bb41de9553af736UL] = "Hasta entonces, qué decir salvo:\r\nBien jugado, damas y caballeros.",
                    [0x8e781aceec208dfeUL] = "Aquí Balista. Esta comisaría está ahora bajo control de la Pandilla Colmena. Todas las salidas están selladas. No hay escape.",
                    [0x8eb45aba1a7af43fUL] = "...con más nieve esperada durante el fin de semana festivo.",
                    [0x8eda0d484d2b9b1aUL] = "¡Guárdate las excusas para el jefe, idiota!",
                    [0x919ac2597112e633UL] = "¡Nadie sale, por orden de Balista!",
                    [0x921185c061452504UL] = "¡Muere! ¡Por orden de Balista!",
                    [0x933e3c19587cd13cUL] = "¡Si quieres algo bien hecho, tienes que hacerlo tú misma!",
                    [0x9445dc6be5a3ee7dUL] = "No sé. Quería interrogarlos o algo. O quizá solo quería fastidiar a esos babosos corporativos.",
                    [0x993a2f48484a41e2UL] = "¡OYE! ¿No tenéis ningún respeto por la ley y el orden!?",
                    [0xa3e0bd0a4c2d32faUL] = "¡Tú... tú... por qué debería...!",
                    [0xa5a988f92c1e63c4UL] = "¿Muerto?!\r\n\r\n¡Quienquiera que seas, acabas de cabrear a la Pandilla Colmena!",
                    [0xa5e7abbb835df100UL] = "PANDILLA COLMENA",
                    [0xa63fb33072e54399UL] = "Mujer misteriosa",
                    [0xa6584a89b26fe7b3UL] = "MATA",
                    [0xa6c6d892eb95e471UL] = "¡No dejéis que los activos escapen!",
                    [0xab522c636a0e6128UL] = "¡No creerás cómo shsobreviví. ¡Te lo contaré luego!",
                    [0xafae86a2590e4b00UL] = "¿Me enviáis una postal, vale?",
                    [0xafc7d444ab3a616bUL] = "Shi buhcáis mi cerveza, ya no queda. Ehtoh maderoh me la confih... quitaron cuando me detuvieron. ¡Me quitaron lah alah, loh bahtardoh!",
                    [0xb212b8ea4802f71aUL] = "¡DERROTA\r\nEl piloto murió!",
                    [0xb7d3d2d176763a19UL] = "Por cierto, me llamo Jeff. ¿Sabes? Ehto podría ser el comienzo de algo hermoho...",
                    [0xbb5a28cd54f65e38UL] = "Esta emisión ha sido patrocinada por MetroCorp: Un Futuro Más Brillante para Ciudad Soleada. ¡Buenas noches!",
                    [0xbb6a540c1ec0e4f4UL] = "¡El ejército de matones fanáticos de Balista tomó rápidamente el control de la comisaría y se ha atrincherado dentro! ¡No está claro si alguien sobrevivió al bárbaro ataque!",
                    [0xbcb3cc0bf22360bdUL] = "¡Aquí Balista! ¡El cobarde de Hagan debe entregarse!",
                    [0xbce92351bca42cf8UL] = "El alcalde considera que su departamento... es INSUFICIENTE para la situación. Deje esto a los profesionales.",
                    [0xbd1b53ade13daa4dUL] = "¡Entretenedlos mientrah trabajo en ehtoh!",
                    [0xbdd49e2f3d6dd1d1UL] = "Ahora, imagino que toca descansar. Un momento de paz, quizá, en algún lugar más allá de esas colinas oscuras.",
                    [0xc09bbd3d2f3fdbccUL] = "¡Escoria mercenaria! ¡Pedí refuerzos, POLIS, no un montón de mercenarios gatillo fácil!",
                    [0xc232981f08e5d7beUL] = "Sé eso PERFECTAMENTE, detective. Buenas noches.",
                    [0xc2df6869edc67547UL] = "MÁTALOS\r\nA\r\nTODOS",
                    [0xc5ad69595973c5cbUL] = "ANARQUÍA",
                    [0xc74a88131e6a22dfUL] = "Hmmm. Primer motor lihto, pero el hegundo podría necehitar unoh retoqueh máh. ¡Entretenedloh un poco máh, chicoh!",
                    [0xc8dea6adab5b0254UL] = "OBEDECE",
                    [0xc96a323fc267e0feUL] = "¡Venga, salgamos de aquí!",
                    [0xcd2a719214a4f9b6UL] = "Balista",
                    [0xcf18e1924041e938UL] = "Quiero todas las salidas selladas. Nadie entra ni sale. Voy a hacerle una visita al Comisario.",
                    [0xd0c865f0a840ceb5UL] = "SIN\r\nPIEDAD",
                    [0xd0ed97895f85a908UL] = "¿Como qué? Ya les estamos disparando. Y nos hemos quedado sin BarreCalles.",
                    [0xd234a886d21a0080UL] = "¡Ríndete, Balista! ¡Hagan está muerto, ya tienes lo que querías!",
                    [0xd844e8b6c449a9dfUL] = "Alfa tango a zeta foxtrot. Desplieguen a los BarreCalles.",
                    [0xdab28176b0d9658fUL] = "¡MANDA!",
                    [0xdb046f5df26c80aeUL] = "El asalto fue una venganza imprudente por la reciente campaña contra el crimen del Comisario Hagan, en la que murieron varios jefes de la Pandilla Colmena.",
                    [0xdc9628a2e5dccd50UL] = "AYUDA",
                    [0xdead4285f0b5615aUL] = "Nel. Nunca volveré a volar... máh vale rendirme y... [gruñe incomprensible].",
                    [0xdf5bab3f13c23da7UL] = "La comisaría 9 fue atacada hoy por la infame Pandilla Colmena. Su líder, conocida solo como Balista, es la reina del crimen desorganizado de nuestra ciudad.",
                    [0xe09dda4e4d949d9dUL] = "¡Además, quien me traiga al comisario, vivo o muerto, se librará de más violencia!",
                    [0xe2a689e0ef6356deUL] = "¿Q-qué demonios está PASANDO ahí fuera?",
                    [0xe2b3e921c2eb78c8UL] = "¡Eh, eres ese prisionero! ¿Cómo demonios sobreviviste? Da igual. Veo que no eres amigo de la Pandilla Colmena. Ayudémonos.",
                    [0xe36d733447235e46UL] = "Presentador",
                    [0xe4d737b422a42442UL] = "¿Pero por qué parar ahora cuando me estoy DIVIRTIENDO TANTO?",
                    [0xe62825a3f17a8e22UL] = "¡Sí, sí! ¡Baja la voz!",
                    [0xe63446bb533998e4UL] = "¡B-Balista!",
                    [0xe9bb19c6c77ce918UL] = "NO",
                    [0xeb6ea4fbdae67a8dUL] = "BALISTA\r\n  ES\r\nREINA",
                    [0xee11f81195a12305UL] = "¿Y matáis a esa loca por mí, vale?",
                    [0xf0656dbb5ab6cab8UL] = "Claro, señora. ¿Quién?",
                    [0xf0a8e2712d23a8b6UL] = "Última hora: Por orden del alcalde, varias unidades de MetroLaw han sido desplegadas para lidiar con los terroristas que tomaron el control de la comisaría de la Comisaría 9 esta noche.",
                    [0xf24946686c8545c2UL] = "No se rinden, ¿verdad?\r\nQuizá es que no saben cómo.",
                    [0xf563e820c21015beUL] = "Ciudad Soleada, 20XX\r\n\r\n",
                    [0xf5aeb95b33b40b2eUL] = "Supongo que tienes razón Frank... Es importante tener principios.",
                    [0xfe1e16ae5a0d8fdbUL] = "¿Por qué McBride trajo a esos luchadores renegados? MetroLaw los atrapará al final, no tiene sentido resistirse.",
                },
                ["pt-BR"] = new()
                {
                    [0x036a7ec59a2378aeUL] = "Entendido, Rainha B.",
                    [0x04288307a2f02760UL] = "Alô. Quero denunciar o paradeiro de uma notória ASSASSINA EM MASSA.",
                    [0x0635c55daced5862UL] = "Não vou ficar aqui a noite toda!",
                    [0x0e8727e75f2dc91eUL] = "Você não machucar Rainha Balista!",
                    [0x0f5797910f6e4222UL] = "Ihaaaa!!!",
                    [0x11102a388b0c488aUL] = "Eu.",
                    [0x1822d75d4c4b2a19UL] = "PIEDADE",
                    [0x18e6bef70932509cUL] = "O Espectador",
                    [0x1ed278cd898a56f2UL] = "Agora shó eshtou eshperando aqueleş bandidos voltarem pra acabar comigo. Não quero mais correr. É uma deshgraça atrás da outra...",
                    [0x1f203f4e59f5cd8dUL] = "O povo hoje em dia...",
                    [0x1f5b7e573cbf4c01UL] = "Uou! Belo tiro, Rainha B!",
                    [0x291202ff73e9e072UL] = "O prefeito chamou o ataque de \"totalmente injusto\". Traremos atualizações ao vivo dessa história emocionante!",
                    [0x29582d73906f8c40UL] = "Mas a luta entre Ordem e Caos ainda não está decidida. A balança vai pender e nossos heróis voltarão a Sunny City.",
                    [0x29b4fe2dbb57ef6aUL] = "MINHA VIDA PELA BALISTAAAAA!!!",
                    [0x2c9e88d31ec5c7d3UL] = "MetroPoli",
                    [0x2cadd26834d97180UL] = "Não deixem fugir! Façam algo!",
                    [0x344caa065b4fa30bUL] = "Ei Frank, me empresta um dólar? Quero comprar um refri da máquina.",
                    [0x345852fa00e98d27UL] = "RAINHA",
                    [0x3567f1bf42f27991UL] = "Ei, vocês são aqueles prisioneiros! Como sobreviveram? Deixa pra lá. Vejo que não são amigos da Gangue da Colmeia. Vamos nos ajudar.",
                    [0x3626754b9f4fce11UL] = "Então você ainda eshtá vivo! Entra!",
                    [0x39b52944cab631faUL] = "Ei, CUIDADO!",
                    [0x3a224d0ee5a8c249UL] = "Sangue! Sangue por BALISTA!",
                    [0x3a9ff2ee65fcda1eUL] = "GANGUE DA COLMEIA\r\n MANDA!",
                    [0x3d230e7daa680c1bUL] = "Balista... a Rainha Balista está morta!",
                    [0x3dbe25089691de83UL] = "Não se preocupem. Eshou firme como uma rocha. E vou VOAR como uma, eshperem só.",
                    [0x40cc3f8a39491e51UL] = "Ela eshtá viva! ELA ESHTÁ VIVA! Embarquem, pessoal!",
                    [0x40fedf513f4bf84fUL] = "BLOCO DE DETENÇÃO A",
                    [0x431202ac48344bf4UL] = "Esta noite só há uma lei: Faça o que seu Ódio mandar!",
                    [0x43f92a5c402137ddUL] = "São muitos... muitos demais!",
                    [0x44cc3f3f7d3fe1e0UL] = "Pelo menos a energia voltou... mas que diabos está acontecendo com as câmeras de segurança?",
                    [0x45112e69a0ede541UL] = "Tem um piloto, prisioneiro como vocês, no Bloco D. Se alguém pode tirar vocês daqui, é ele. Eu levo vocês até lá – mas primeiro me ajudem a matar a Balista.",
                    [0x46633bc8a3feeadaUL] = "Droga! Algo errado com os motoresh. Que idiota mexeu nishto? Me dá um minuto pra olhar embaixo do capô...",
                    [0x4777cc942d9250faUL] = "Pode dizer aos seus homens para relaxarem, detetive. Nós assumimos daqui.",
                    [0x48f915a5bbed5545UL] = "Barulho estranho... Vou ignorar.",
                    [0x4cc55697b6b10e11UL] = "Vocês não vão se livrar de mim tão fácil, amantes de porcos!",
                    [0x4cdedc0731675745UL] = "Não é ESSE o ponto! É sobre... PRINCÍPIOS! Onde a Gangue da Colmeia estaria se começássemos a PAGAR pelas coisas?",
                    [0x4df8d1bea7423792UL] = "Comprar um refri? COMPRAR um refri?! Você é um BANDIDO! Tem um TACO! É só QUEBRAR essa porcaria!",
                    [0x4e52106b24fc9771UL] = "Tá, vocês me convenceram. Vamos voar daqui!",
                    [0x4fea2fa39f3b3823UL] = "Bem feito! Não sei o que o McBride trama, mas é bom policial. Não restam muitos nesta cidade...",
                    [0x52a5a79ed1d29c03UL] = "Muitos apontam os eventos como prova da obsolescência da polícia tradicional, e que a segurança privatizada é o futuro.",
                    [0x5391db195f195110UL] = "Uma fuga shsuave, considerando tudo!",
                    [0x54b686163fa4490fUL] = "RUHAHAAAARRR HUARRRR!",
                    [0x5954a097af2969f2UL] = "...EMERGÊNCIA!!! Abandonem a nave!",
                    [0x5a7b270b6fc84783UL] = "Obrigado pela ajuda. É melhor saírem daqui. Para longe de Sunny City.",
                    [0x5dc60337c07f4fe1UL] = "Sunny City, 20XX\r\n\r\n9º Distrito",
                    [0x5e55eaeb18d2b7c8UL] = "GANGUE\r\nDA COLMEIA\r\nMANDA",
                    [0x60cc6f21806e3e1cUL] = "Mfgllll mfwrrrr! MFWRRRR!",
                    [0x620282fb56b61254UL] = "Oooh... Não sei, parece muito trabalho... Mais fácil só...",
                    [0x65d92816d864926eUL] = "A todos meus guerreiros, meus fiéis berserkers: esmaguem os últimos focos de resistência! Tragam-me a cabeça do Comissário Hagan!",
                    [0x66d57fd83ba780ceUL] = "Chega! NINGUÉM vai entrar! Por mais que IMPLOR EM!",
                    [0x6b2c32be2d6e8929UL] = "Matem os prisioneiros também! Já temos guerreiros suficientes!",
                    [0x6d1da39229b50eb2UL] = "Ouviu a dama, tira. Hora de dizer boa noite!",
                    [0x6e2d3cb39ba594cbUL] = "SEUS DESGRAÇADOS! Vocês não vão se safar dessa!",
                    [0x6f48c5680a6578a8UL] = "Mexa shua bunda!",
                    [0x6ffcc22b3a80afd2UL] = "Socorro! Está atrás de mim!",
                    [0x7032c1ee00e8c277UL] = "Jeff",
                    [0x70818f5012b2a6b9UL] = "Ok, vejamosh aqui. Preferia meu fiel avião, mash... ishto serve. Se eu achar a ignição. Ah, aqui eshtá.",
                    [0x70897260e656a02cUL] = "BLOCO",
                    [0x72a8dd799de66b83UL] = "SAÍDA",
                    [0x74d1004c33a4cf82UL] = "Eshte troço é velho até pros meus padrões... Onde vai eshta peça? Não, não é aqui...",
                    [0x76593c4f11889014UL] = "Quero dizer, qual o shentido se eles podem shó... hmm... aquilo é...?",
                    [0x76bae89ee56047a0UL] = "Deus nos salve – é a Gangue da Colmeia!",
                    [0x794b42e6e43d51acUL] = "Não.",
                    [0x80dc943a46520f6cUL] = "Ei, chefe! Quero minha ligação!",
                    [0x87ee43f95113b100UL] = "MATEM\r\n  TODOS\r\nTIRAS",
                    [0x8ac3573c90cfbc94UL] = "Então vai virar meus próprios homens contra mim?! Sua maligna, fedorenta, sanguinária...",
                    [0x8b374962aea1e30eUL] = "Ha! Nem pensar!",
                    [0x8b3bc239dedf1bc0UL] = "Merda, estão vindo! Escuta. Tem um elevador atrás da porta atrás de você. Vou tentar achar outro caminho lá pra cima. Te encontro lá – espero.",
                    [0x8b3bd9f00d1c3605UL] = "Não! Como entraram? SOCORRO!!",
                    [0x8b8b89dc8de8ecf6UL] = "Matem-nos.",
                    [0x8bb41de9553af736UL] = "Até lá, o que dizer senão:\r\nBem jogado, senhoras e senhores.",
                    [0x8e781aceec208dfeUL] = "Aqui é Balista. Esta delegacia está sob controle da Gangue da Colmeia. Todas as saídas seladas. Não há escapatória.",
                    [0x8eb45aba1a7af43fUL] = "...com mais neve esperada para o feriado.",
                    [0x8eda0d484d2b9b1aUL] = "Guarde suas desculpas pro chefe, idiota!",
                    [0x919ac2597112e633UL] = "Ninguém sai, por ordem da Balista!",
                    [0x921185c061452504UL] = "Morra! Por ordem da Balista!",
                    [0x933e3c19587cd13cUL] = "Se quer algo bem feito, faça você mesma!",
                    [0x9445dc6be5a3ee7dUL] = "Sei lá. Queria interrogá-los ou algo assim. Ou só quis ferrar aqueles babacas corporativos.",
                    [0x993a2f48484a41e2UL] = "EI! Vocês não têm nenhum respeito pela lei e ordem?!",
                    [0xa3e0bd0a4c2d32faUL] = "Seu... seu... por que eu deveria...!",
                    [0xa5a988f92c1e63c4UL] = "Morto?!\r\n\r\nSeja quem for, você irritou a Gangue da Colmeia!",
                    [0xa5e7abbb835df100UL] = "GANGUE DA COLMEIA",
                    [0xa63fb33072e54399UL] = "Desconhecida",
                    [0xa6584a89b26fe7b3UL] = "MATE",
                    [0xa6c6d892eb95e471UL] = "Não deixem os ativos escaparem!",
                    [0xab522c636a0e6128UL] = "Você não vai acreditar como shobrevivi. Te conto depois!",
                    [0xafae86a2590e4b00UL] = "Me manda um cartão postal, tá?",
                    [0xafc7d444ab3a616bUL] = "She eshtão atrás da minha cerveja, acabou. Eshes tiras confish... levaram quando me prenderam. Levaram minhas ashas, os deshgraçados!",
                    [0xb212b8ea4802f71aUL] = "DERROTA\r\nO piloto foi morto!",
                    [0xb7d3d2d176763a19UL] = "Aliás, meu nome é Jeff. Shabe, ishto pode ser o começo de algo lindo...",
                    [0xbb5a28cd54f65e38UL] = "Transmissão patrocinada pela MetroCorp: Um Futuro Mais Brilhante para Sunny City. Boa noite!",
                    [0xbb6a540c1ec0e4f4UL] = "Os fanáticos de Balista tomaram a delegacia e se trancaram lá dentro! Não se sabe se alguém sobreviveu ao ataque bárbaro!",
                    [0xbcb3cc0bf22360bdUL] = "Aqui é Balista! O covarde do Hagan deve se entregar!",
                    [0xbce92351bca42cf8UL] = "O prefeito considera seu departamento... INSUFICIENTE para a situação. Deixe com os profissionais.",
                    [0xbd1b53ade13daa4dUL] = "Segurem-nos enquanto conserto eshta coisa!",
                    [0xbdd49e2f3d6dd1d1UL] = "Agora, imagino que um descanso seja merecido. Um momento de paz, além daquelas colinas escuras.",
                    [0xc09bbd3d2f3fdbccUL] = "Seus mercenários escrotos! Pedi reforços – POLICIAIS, não um bando de mercenários com dedo no gatilho!",
                    [0xc232981f08e5d7beUL] = "Eu sei MUITO BEM disso, detetive. Boa noite.",
                    [0xc2df6869edc67547UL] = "MATEM\r\nTODOS",
                    [0xc5ad69595973c5cbUL] = "ANARQUIA",
                    [0xc74a88131e6a22dfUL] = "Hmmm. Primeiro motor pronto, mas o shegundo precisa de ajustes também. Segurem-nos mais um pouco!",
                    [0xc8dea6adab5b0254UL] = "OBEDEÇA",
                    [0xc96a323fc267e0feUL] = "Vamos, vamos shair daqui!",
                    [0xcd2a719214a4f9b6UL] = "Balista",
                    [0xcf18e1924041e938UL] = "Quero todas as saídas seladas. Ninguém entra nem sai. Vou fazer uma visita ao Comissário.",
                    [0xd0c865f0a840ceb5UL] = "SEM\r\nPIEDADE",
                    [0xd0ed97895f85a908UL] = "Como o quê? Já estamos atirando neles. E ficamos sem Varredores.",
                    [0xd234a886d21a0080UL] = "Desiste, Balista! Hagan está morto – você conseguiu o que queria!",
                    [0xd844e8b6c449a9dfUL] = "Alfa tango para zeta foxtrot. Acionem os Varredores.",
                    [0xdab28176b0d9658fUL] = "MANDA",
                    [0xdb046f5df26c80aeUL] = "O ataque foi vingança por campanha recente do Comissário Hagan, onde vários líderes da Gangue morreram.",
                    [0xdc9628a2e5dccd50UL] = "SOCORRO",
                    [0xdead4285f0b5615aUL] = "Não. Nunca mais vou voar... melhor deshishtir e só [resmungo incompreensível].",
                    [0xdf5bab3f13c23da7UL] = "O 9º Distrito foi atacado hoje pela infame Gangue da Colmeia. Sua líder, conhecida só como Balista, é a rainha autoproclamada do crime.",
                    [0xe09dda4e4d949d9dUL] = "Além disso, quem me trouxer o comissário – vivo ou morto – será poupado!",
                    [0xe2a689e0ef6356deUL] = "Q-que diabos está acontecendo lá fora?",
                    [0xe2b3e921c2eb78c8UL] = "Ei, você é aquele prisioneiro! Como sobreviveu? Deixa pra lá. Vejo que não é amigo da Gangue da Colmeia. Vamos nos ajudar.",
                    [0xe36d733447235e46UL] = "Âncora",
                    [0xe4d737b422a42442UL] = "Mas por que parar agora quando estou me DIVERTINDO TANTO?",
                    [0xe62825a3f17a8e22UL] = "Tá, tá. Baixa o volume!",
                    [0xe63446bb533998e4UL] = "B-Balista!",
                    [0xe9bb19c6c77ce918UL] = "NÃO",
                    [0xeb6ea4fbdae67a8dUL] = "BALISTA\r\n  É\r\nRAINHA",
                    [0xee11f81195a12305UL] = "E matem aquela maluca por mim, tá?",
                    [0xf0656dbb5ab6cab8UL] = "Claro, senhora. Quem?",
                    [0xf0a8e2712d23a8b6UL] = "Urgente: Por ordem do prefeito, várias unidades da MetroLaw foram enviadas contra terroristas que tomaram o 9º Distrito.",
                    [0xf24946686c8545c2UL] = "Eles não desistem, né?\r\nTalvez seja porque não sabem como.",
                    [0xf563e820c21015beUL] = "Sunny City, 20XX\r\n\r\n",
                    [0xf5aeb95b33b40b2eUL] = "Acho que tem razão, Frank... É importante ter princípios.",
                    [0xfe1e16ae5a0d8fdbUL] = "Por que o McBride trouxe esses lutadores renegados? A MetroLaw vai pegá-los no fim – não adianta resistir.",
                },
                ["ru-RU"] = new()
                {
                    [0x036a7ec59a2378aeUL] = "Понял, Королева Би.",
                    [0x04288307a2f02760UL] = "Здравствуйте. Хочу сообщить, где находится один печально известный МАССОВЫЙ УБИЙЦА.",
                    [0x0635c55daced5862UL] = "Не собираюсь торчать тут всю ночь!",
                    [0x0e8727e75f2dc91eUL] = "Ты не трогать Королеву Балисту!",
                    [0x0f5797910f6e4222UL] = "Йиии-хааа!!!",
                    [0x11102a388b0c488aUL] = "Я.",
                    [0x1822d75d4c4b2a19UL] = "ПОЩАДА",
                    [0x18e6bef70932509cUL] = "Наблюдатель",
                    [0x1ed278cd898a56f2UL] = "А тепер жду, когда эти бандиты вернутся и добьют меня. Бежать больше нет шил. Одно за другим...",
                    [0x1f203f4e59f5cd8dUL] = "Ну и люди нынче...",
                    [0x1f5b7e573cbf4c01UL] = "Вуух! Классный выстрел, Королева Би!",
                    [0x291202ff73e9e072UL] = "Мэр кратко прокомментировал атаку, назвав ее «крайне несправедливой». Мы будем вести прямой эфир по мере развития событий!",
                    [0x29582d73906f8c40UL] = "Но борьба Порядка и Хаоса еще не решена. Чаша весов качнется, и наши герои снова и снова будут возвращаться в Санни-Сити.",
                    [0x29b4fe2dbb57ef6aUL] = "ЖИЗНЬ ЗА БАЛИСТУУУ!!!",
                    [0x2c9e88d31ec5c7d3UL] = "Метрокоп",
                    [0x2cadd26834d97180UL] = "Не дайте им уйти! Сделайте что-нибудь!",
                    [0x344caa065b4fa30bUL] = "Эй, Фрэнк, одолжи бакс? Хочу газировку из автомата.",
                    [0x345852fa00e98d27UL] = "КОРОЛЕВА",
                    [0x3567f1bf42f27991UL] = "Эй, вы те пленники! Как вы выжили? Неважно. Вижу, вы не друзья Банде Улья. Давайте помогать друг другу.",
                    [0x3626754b9f4fce11UL] = "О, ты еще жив! Залезай!",
                    [0x39b52944cab631faUL] = "Эй, БЕРЕГИСЬ!",
                    [0x3a224d0ee5a8c249UL] = "Кровь! Кровь во имя БАЛИСТЫ!",
                    [0x3a9ff2ee65fcda1eUL] = "БАНДА УЛЬЯ\r\n РУЛИТ!",
                    [0x3d230e7daa680c1bUL] = "Балиста... Королева Балиста мертва!",
                    [0x3dbe25089691de83UL] = "Не волнуйтешь. Я тверд как шкала. И ЛЕТАТЬ буду как шкала, фот увидите.",
                    [0x40cc3f8a39491e51UL] = "Она жива! ЖИВА! Запрыгивайте на борт, парни!",
                    [0x40fedf513f4bf84fUL] = "БЛОК ЗАДЕРЖАНИЯ А",
                    [0x431202ac48344bf4UL] = "Сегодня есть лишь один закон: делай то, что велит тебе Ненависть!",
                    [0x43f92a5c402137ddUL] = "Их слишком... слишком много!",
                    [0x44cc3f3f7d3fe1e0UL] = "Хоть электричество вернулось... но что за чертовщина с камерами?",
                    [0x45112e69a0ede541UL] = "Тут есть пилот, такой же пленник. Он в блоке D. Если кто и вытащит вас отсюда, то он. Я доведу вас до него — но сначала помогите убить Балисту.",
                    [0x46633bc8a3feeadaUL] = "Черт! Что-то не так ш двигателями. Какой болван их делал? Дайте минуту под капот заглянуть...",
                    [0x4777cc942d9250faUL] = "Скажи своим людям расслабиться, детектив. Дальше мы сами.",
                    [0x48f915a5bbed5545UL] = "Странный шум... Не обращу внимания.",
                    [0x4cc55697b6b10e11UL] = "Вы так легко от меня не избавитесь, любители копов!",
                    [0x4cdedc0731675745UL] = "Дело не в ЭТОМ! Дело в... ПРИНЦИПАХ! Что будет с Бандой Улья, если мы начнем ПЛАТИТЬ за вещи?",
                    [0x4df8d1bea7423792UL] = "Купить газировку? КУПИТЬ газировку?! Ты БАНДИТ! У тебя есть БИТА! Просто РАЗБЕЙ эту чертову штуку!",
                    [0x4e52106b24fc9771UL] = "Ладно, вы меня убедили. Дафайте улитаем отшюда!",
                    [0x4fea2fa39f3b3823UL] = "Так им и надо! Не знаю, что задумал Макбрайд, но он хороший коп. Таких в городе почти не осталось...",
                    [0x52a5a79ed1d29c03UL] = "Многие считают сегодняшние события доказательством устарелости обычной полиции и того, что полная приватизация — будущее охраны порядка.",
                    [0x5391db195f195110UL] = "Мягкая посадка, ущитывая обштоятельштва!",
                    [0x54b686163fa4490fUL] = "РУХААААРРР ХУАРРРР!",
                    [0x5954a097af2969f2UL] = "...ЧРЕЗВЫЧАЙКА!!! Покинуть судно!",
                    [0x5a7b270b6fc84783UL] = "Спасибо за помощь. Вам лучше валить отсюда. Подальше от Санни-Сити.",
                    [0x5dc60337c07f4fe1UL] = "Санни-Сити, 20XX\r\n\r\n9-й участок",
                    [0x5e55eaeb18d2b7c8UL] = "БАНДА\r\nУЛЬЯ\r\nРУЛИТ",
                    [0x60cc6f21806e3e1cUL] = "Мфггллл мфвррр! МФВРРРР!",
                    [0x620282fb56b61254UL] = "Ооо... Не знаю, это столько возни... Проще просто...",
                    [0x65d92816d864926eUL] = "Всем моим воинам, верным берсеркам: раздавите последние очаги сопротивления! Принесите мне голову комиссара Хагана!",
                    [0x66d57fd83ba780ceUL] = "Хватит! НИКТО не войдет! Как бы ни УМОЛЯЛИ!",
                    [0x6b2c32be2d6e8929UL] = "Убейте и пленников! Бойцов нам хватает!",
                    [0x6d1da39229b50eb2UL] = "Ты слышал даму, легавый. Пора баиньки!",
                    [0x6e2d3cb39ba594cbUL] = "Вы, УБЛЮДКИ! Вам это с рук не сойдет!",
                    [0x6f48c5680a6578a8UL] = "Шевелись, задница!",
                    [0x6ffcc22b3a80afd2UL] = "Помогите! Оно за мной!",
                    [0x7032c1ee00e8c277UL] = "Джефф",
                    [0x70818f5012b2a6b9UL] = "Так, пофмотрим. Я бы швой шамолет фзял, но... и это шойдет. Ешли найду зажигание. А, фот оно.",
                    [0x70897260e656a02cUL] = "БЛОК",
                    [0x72a8dd799de66b83UL] = "ВЫХОД",
                    [0x74d1004c33a4cf82UL] = "Эта штука штарая даже по моим меркам... Куда эта деталь? Нет, не так...",
                    [0x76593c4f11889014UL] = "Ну то есть, какой шмышл, ешли они могут прочто... хм... это что...",
                    [0x76bae89ee56047a0UL] = "Спаси нас Боже — это Банда Улья!",
                    [0x794b42e6e43d51acUL] = "Неа.",
                    [0x80dc943a46520f6cUL] = "Эй, шеф! Хочу свой звонок!",
                    [0x87ee43f95113b100UL] = "УБЕЙ\r\n  ВСЕХ\r\nКОПОВ",
                    [0x8ac3573c90cfbc94UL] = "Так ты натравишь моих людей на меня?! Ах ты злобная, вонючая, кровожадная...",
                    [0x8b374962aea1e30eUL] = "Ха! Не дождешься!",
                    [0x8b3bc239dedf1bc0UL] = "Черт, они идут! Слушайте. За дверью позади вас есть лифт. Я попробую найти другой путь наверх. Встретимся там — надеюсь.",
                    [0x8b3bd9f00d1c3605UL] = "Нет! Как вы вошли? ПОМОГИТЕ!!",
                    [0x8b8b89dc8de8ecf6UL] = "Убейте их.",
                    [0x8bb41de9553af736UL] = "А пока что сказать, кроме как:\r\nОтлично сыграно, дамы и господа.",
                    [0x8e781aceec208dfeUL] = "Говорит Балиста. Участок теперь под контролем Банды Улья. Все выходы перекрыты. Сбежать невозможно.",
                    [0x8eb45aba1a7af43fUL] = "...с ухудшением погоды и снегопадом на выходных.",
                    [0x8eda0d484d2b9b1aUL] = "Прибереги отмазки для босса, идиот!",
                    [0x919ac2597112e633UL] = "Никто не выйдет, по приказу Балисты!",
                    [0x921185c061452504UL] = "Умри! По приказу Балисты!",
                    [0x933e3c19587cd13cUL] = "Хочешь сделать хорошо — сделай сама!",
                    [0x9445dc6be5a3ee7dUL] = "Не знаю. Хотел допросить или типа того. Или просто насолить этим корпоративным слизнякам.",
                    [0x993a2f48484a41e2UL] = "ЭЙ! У вас вообще есть уважение к закону?!",
                    [0xa3e0bd0a4c2d32faUL] = "Ты... ты... да я тебя...!",
                    [0xa5a988f92c1e63c4UL] = "Мертв?!\r\n\r\nКто бы ты ни был, ты разозлил Банду Улья!",
                    [0xa5e7abbb835df100UL] = "БАНДА УЛЬЯ",
                    [0xa63fb33072e54399UL] = "Незнакомка",
                    [0xa6584a89b26fe7b3UL] = "УБЕЙ",
                    [0xa6c6d892eb95e471UL] = "Не дайте объектам сбежать!",
                    [0xab522c636a0e6128UL] = "Не поверишь, как я выжил. Расскажу потом!",
                    [0xafae86a2590e4b00UL] = "Откротку пришлете, а?",
                    [0xafc7d444ab3a616bUL] = "Ешли ищете мое пиво, его нет. Эти копы ш... ш... забрали его, когда повязали меня. Забрали мои крылья, гады!",
                    [0xb212b8ea4802f71aUL] = "ПОРАЖЕНИЕ\r\nПилот погиб!",
                    [0xb7d3d2d176763a19UL] = "Кстати, я Джефф. Знаешь, это может быть началом чего-то прекрасного...",
                    [0xbb5a28cd54f65e38UL] = "Трансляцию спонсирует МетроКорп: Светлое будущее для Санни-Сити. Спокойной ночи!",
                    [0xbb6a540c1ec0e4f4UL] = "Армия фанатичных головорезов Балисты быстро захватила участок и забаррикадировалась внутри! Неизвестно, выжил ли кто-то в этой резне!",
                    [0xbcb3cc0bf22360bdUL] = "Говорит Балиста! Трус Хаган должен сдаться!",
                    [0xbce92351bca42cf8UL] = "Мэр считает ваш отдел... НЕДОСТАТОЧНЫМ для такой ситуации. Предоставьте это профессионалам.",
                    [0xbd1b53ade13daa4dUL] = "Задержите их, пока я фозьусь ш этой штукой!",
                    [0xbdd49e2f3d6dd1d1UL] = "Думаю, пора отдохнуть. Миг покоя, где-то за теми темными холмами.",
                    [0xc09bbd3d2f3fdbccUL] = "Вы, наемные подонки! Я просил подкрепление — КОПОВ, а не кучку наемников-отморозков!",
                    [0xc232981f08e5d7beUL] = "Я прекрасно это ЗНАЮ, детектив. Спокойной ночи.",
                    [0xc2df6869edc67547UL] = "УБЕЙТЕ\r\nИХ\r\nВСЕХ",
                    [0xc5ad69595973c5cbUL] = "АНАРХИЯ",
                    [0xc74a88131e6a22dfUL] = "Хм. Первый двигатель готов, а фторой надо подшаманить. Задержите их еще немного, парни!",
                    [0xc8dea6adab5b0254UL] = "ПОВИНУЙСЯ",
                    [0xc96a323fc267e0feUL] = "Давай, сваливаем отсюда!",
                    [0xcd2a719214a4f9b6UL] = "Балиста",
                    [0xcf18e1924041e938UL] = "Приказываю опечатать все выходы. Никто не войдет и не выйдет. Навещу-ка Комиссара.",
                    [0xd0c865f0a840ceb5UL] = "БЕЗ\r\nПОЩАДЫ",
                    [0xd0ed97895f85a908UL] = "Что, например? Мы и так по ним стреляем. И Чистильщики кончились.",
                    [0xd234a886d21a0080UL] = "Сдавайся, Балиста! Хаган мертв — ты получила, что хотела!",
                    [0xd844e8b6c449a9dfUL] = "Альфа танго — зета фокстрот. Выпускайте Чистильщиков.",
                    [0xdab28176b0d9658fUL] = "РУЛИТ",
                    [0xdb046f5df26c80aeUL] = "Нападение, вероятно, было местью за недавнюю кампанию комиссара Хагана, в ходе которой погибли несколько главарей Банды Улья.",
                    [0xdc9628a2e5dccd50UL] = "ПОМОГИТЕ",
                    [0xdead4285f0b5615aUL] = "Неа. Больше не летать... проще шдаться и... [бормочет].",
                    [0xdf5bab3f13c23da7UL] = "Сегодня участок 9-го округа атакован печально известной Бандой Улья. Ее лидер, женщина, известная лишь как Балиста — самопровозглашенная королева городского беспредела.",
                    [0xe09dda4e4d949d9dUL] = "Более того, каждый, кто приведет комиссара — живым или мертвым — избежит дальнейшего насилия!",
                    [0xe2a689e0ef6356deUL] = "Ч-что за черт ТУТ происходит?",
                    [0xe2b3e921c2eb78c8UL] = "Эй, ты тот пленник! Как ты выжил? Неважно. Вижу, ты не друг Банде Улья. Давай помогать друг другу.",
                    [0xe36d733447235e46UL] = "Диктор",
                    [0xe4d737b422a42442UL] = "А зачем останавливаться, когда так ВЕСЕЛО?",
                    [0xe62825a3f17a8e22UL] = "Да, да. Потише!",
                    [0xe63446bb533998e4UL] = "Б-Балиста!",
                    [0xe9bb19c6c77ce918UL] = "НЕТ",
                    [0xeb6ea4fbdae67a8dUL] = "БАЛИСТА\r\n  ЭТО\r\nКОРОЛЕВА",
                    [0xee11f81195a12305UL] = "И убейте для меня эту чокнутую, ладно?",
                    [0xf0656dbb5ab6cab8UL] = "Конечно, мэм. Кто?",
                    [0xf0a8e2712d23a8b6UL] = "Срочная новость: по приказу мэра на борьбу с террористами, захватившими 9-й участок, направлены отряды MetroLaw.",
                    [0xf24946686c8545c2UL] = "Они не сдаются, да?\r\nМожет, просто не умеют.",
                    [0xf563e820c21015beUL] = "Санни-Сити, 20XX\r\n\r\n",
                    [0xf5aeb95b33b40b2eUL] = "Наверно, ты прав, Фрэнк... Важно иметь принципы.",
                    [0xfe1e16ae5a0d8fdbUL] = "Зачем Макбрайд привел этих отморозков? MetroLaw их все равно достанет — нет смысла сопротивляться.",
                },
            },
            ["363e25b5-c239-4a2e-bfb8-837535807f18"] = new()
            {
                ["es-419"] = new()
                {
                    [0x00c828920feb30a9UL] = "No pareces un nazi, ¿cómo demonios saliste vivo?",
                    [0x00f894c753526ecaUL] = "Ah, mi pequeño... han matado al pobre Kriegbär #2.",
                    [0x04ea71f543f7a181UL] = "¡Pero también mi mayor ERROR! Es hora de rectificar ese error. ¡Frau Sturmbannführer! ¡Tráigamelos!",
                    [0x068bd1e0ac21a69eUL] = "Ah, cierto... nazis.",
                    [0x130cb8e004b1746fUL] = "O Tannenbaum, o Tannenbaum,\nwie treu sind deine Blätter!",
                    [0x136b271625dfa814UL] = "No. Sigamos adelante. Este castillo aún no está muerto.",
                    [0x16c94d4cdbfbd83aUL] = "¡Nein, nein, nein! ¡Demasiado tarde otra vez!",
                    [0x17594f4811a66fb1UL] = "Da... ¿dónde estamos?",
                    [0x18ee39dc7f64b7acUL] = "El símbolo del Sol de Seis Lados... así que estamos en manos de la SSS.",
                    [0x18fcc16fbb3dd6a8UL] = "No sé, pero lo voy a averiguar.",
                    [0x19e22d8dbc2511f3UL] = "¡Destruyan los cañones! ¡Una granada en el cañón bastará!",
                    [0x1a5a9e011c4e5fe2UL] = "Lt. Eugene McBride, ejército de EE. UU....",
                    [0x1adf386486cd3f55UL] = "¡Tengo que destruir esos cañones!",
                    [0x1b7ada164ffa40e3UL] = "¡Ese no es un nombre de verdad!",
                    [0x1c07e9eecf9d03ecUL] = "Creo que tenían la idea de convertir a los seres humanos en armas.",
                    [0x1ffaba68dba5eb7dUL] = "No importa, ya me lo contarán después. ¡Mis órdenes son sacarlos de aquí como sea!",
                    [0x2146921baf773954UL] = "No sé, pero yo no me quedo aquí.",
                    [0x21cbcb67482f6dd3UL] = "Lt. Eugene McBride. Americano.",
                    [0x21faa64bab773212UL] = "Me siento... diferente. Más fuerte... más resistente.",
                    [0x26229618cf6b2706UL] = "Con calma ahora...",
                    [0x263ef99ee3dd3bdfUL] = "(¡Y pronto el propio Führer se arrodillará ante Fritzliebe! ¡Ja ja!)",
                    [0x266ca9e1237fd940UL] = "¿Qué ha dicho, doctor?",
                    [0x29b3a84d1bd5b60fUL] = "Hay nieve... pero no hay sol. Debe ser de noche afuera.",
                    [0x29c8a93ca01dfe83UL] = "Da. Recuerdo que me capturaron... me torturaron...",
                    [0x2d7f0f37395c44b3UL] = "¿Qué eres? ¿Alemán? ¿Británico?",
                    [0x2e43b75b784acb3aUL] = "No sé, pero no pienso volver a uno de esos tanques.",
                    [0x310d3b80502503b9UL] = "¡Entren! ¡Rápido!",
                    [0x33dba133326568c5UL] = "¡Una granada en el cañón debería bastar!",
                    [0x34e13ec981301157UL] = "¡No podrán pasar ahora, malditos bastardos!",
                    [0x3702712331c60bbbUL] = "¡NEIN! ¡El árbol de Navidad no se toca!",
                    [0x37d4da79f91ea69dUL] = "¡Pero también tengo muchos avances MECÁNICOS que mostrarte!",
                    [0x39108d3782fcc184UL] = "¡No podrán pasar por ESA!",
                    [0x399d69478283bf0aUL] = "¡Ah, pobre Kriegbär #2! Era una de mis criaturas favoritas. Oh, bueno... Admito mi derrota. Entren, y discutamos los términos de mi rendición.",
                    [0x39b11fc2eb9591f7UL] = "¿Esperamos aquí? Quizá vengan a rescatarnos.",
                    [0x3acef01069bf7698UL] = "¡Buen trabajo! No sé ustedes, pero yo prefiero estar bajo tierra.",
                    [0x3bb78c987c37ef80UL] = "Supongo que conservaron nuestra ropa vieja.",
                    [0x3c42fab09bee3aceUL] = "¡Cierren esa puerta!",
                    [0x3d0b9534cd0767daUL] = "Du grünst nicht nur zur Sommerzeit,\nNein auch im Winter, wenn es schneit!",
                    [0x3d211a9f797e8abcUL] = "¡Maldito ruido! ¡Tengo que acabar con esos cañones!",
                    [0x3f1367c4cc04d1ceUL] = "Urrrgh... mi cabeza...",
                    [0x3f57a8067643aaf1UL] = "¡¡¡Attentaten!!!",
                    [0x3f7b9829b86ec16dUL] = "¿Hay un ataque aéreo en curso? Podría ser nuestra oportunidad de escapar...",
                    [0x421bf0c8717484ceUL] = "Una sociedad secreta dentro del Reich. Investigación secreta: armas, bioingeniería, ocultismo...",
                    [0x431937b187f1272fUL] = "Esa no es una bandera nazi común. ¿Qué es esto?",
                    [0x455df089e85d4bebUL] = "¡Queda un cañón!",
                    [0x46ee9a6b83e2eaf5UL] = "¡De nuevo, desde el principio! ¡Y con más sentimiento esta vez!",
                    [0x486ff7ab0719fa17UL] = "Le preguntaré a ese científico que nos torturó... ¡mientras le aprieto su cuello nazi!",
                    [0x496af45538186714UL] = "Extraño... nunca fui un gran luchador, ¡pero ahora me siento imparable!",
                    [0x4b729df370265d0aUL] = "¡Pero también mi mayor ERROR! Es hora de rectificar ese error. ¡Frau Sturmbannführer! ¡Tráigame al espécimen!",
                    [0x4babb86958a61d60UL] = "Yo también me siento en excelente condición física...",
                    [0x4bb1cb28780395f0UL] = "¡Funciona! ¡Faltan dos cañones!",
                    [0x4bd699fb74d17592UL] = "¡Esto es injusto!",
                    [0x4c7ea1bb00311aacUL] = "¡Tenemos que volarlos desde ADENTRO!",
                    [0x50b1af47c674d007UL] = "¡Buenas noches, Dr. Fritzliebe! ¿Cómo va el proyecto Überkämpfer?",
                    [0x519c7a5ff358e4c4UL] = "Solo que son nazis. De la peor calaña.",
                    [0x53192b0aa2e141ffUL] = "¡Intenten lanzar las granadas DENTRO de los cañones!",
                    [0x537f76c41d40d6cbUL] = "¡Mein Gott! ¡Deténganlos!",
                    [0x5712908027cd5023UL] = "No parecen nazis, ¿cómo demonios salieron vivos?",
                    [0x5767d170e5d4e177UL] = "¡He dicho, HEIL HITLER!",
                    [0x57ed6136f8836ba7UL] = "¡Segunda válvula! ¡Cierren la puerta!",
                    [0x593a7092b87f94baUL] = "¡Verdammt! ¡Un ataque aéreo de los Aliados!",
                    [0x5b1a6ebf6ea7465eUL] = "¡Excelentemente, Herr Sturmbannführer! ¡Los prisioneros están respondiendo extraordinariamente bien a la fórmula! ¡Pronto el Führer tendrá su ejército imparable!",
                    [0x5bc1e6c5102e900fUL] = "Supongo que debieron pensarlo dos veces.",
                    [0x5eae866eb3ba9881UL] = "¡La puerta está abierta! ¡Entren!",
                    [0x5f9ed0775cd2d462UL] = "Lo llaman 'Die Sechs-Seitige Sonne'. Son malas noticias.",
                    [0x612c5f5890b06a4dUL] = "¡Aaaaaaaah!",
                    [0x6225ce9cb05fbf29UL] = "¿Qué sabes de la SSS?",
                    [0x62840e40cb928a25UL] = "Deben ser todas esas vitaminas en las que nos hacían nadar...",
                    [0x62f96b2e5c9ddd1eUL] = "¡Nazis!",
                    [0x6330a806d40f3cdcUL] = "¡¡¡HNNNARRRRRRRHHH!!!",
                    [0x6361c1d29798d152UL] = "Bien dicho. Entonces ya tienes una idea de a qué nos enfrentamos.",
                    [0x63b1bc586efa968cUL] = "La BIOQUÍMICA es mi especialidad, es cierto...",
                    [0x64edc3775470fac9UL] = "¡No me llevarán vivo, malditos!",
                    [0x6912caa2276adbb7UL] = "¡¿Qué demonios fue eso?!",
                    [0x697cde99d527e9a5UL] = "Estos nazis no oponen mucha resistencia, ¿verdad?",
                    [0x6dc8d99282b85e62UL] = "¿Yo? Mi nombre...",
                    [0x6e14c9685d7edd2bUL] = "¡Tengo que abrir esa puerta! Esa válvula parece la correcta...",
                    [0x6ec71031388eec00UL] = "¡¿Y ahora cómo demonios cierro la puerta?!",
                    [0x6f47bc553da9b8e5UL] = "*cof* ¡Arrrrrgh... malditos cerdos! Me han matado... ¡Pero ninguno de ustedes saldrá vivo de aquí!",
                    [0x6fa7b2bcfe086ad3UL] = "¿Hay alguna salida a la superficie?",
                    [0x6ff7c93100bf1649UL] = "Tendré que desarmarlos y empezar de nuevo. ¡Y esta vez serán perfectos!",
                    [0x700f189385300980UL] = "Una granada en el cañón debería callar esos cañones...",
                    [0x74e42ee050e494aeUL] = "¿Y tú, tipo duro? ¿Cómo te llaman?",
                    [0x774336bb6f239c56UL] = "Como quieras.",
                    [0x7853d8633fd979b0UL] = "¡Prueben esa válvula roja!",
                    [0x7c20e94fb4650a48UL] = "Kriegbär #2",
                    [0x7c9ab3548d1d56fdUL] = "Marcel Marie, Resistencia francesa.",
                    [0x7ec8470fa0f88a10UL] = "¡Shhh! ¡Escuchen! ¿Qué es eso?",
                    [0x81e08fcf3b26b2c0UL] = "¡Ah, hijo mío! Has llegado tan lejos. Cómo me enorgullece. ¡Eres realmente mi mayor TRIUNFO científico!",
                    [0x829963066c214aaaUL] = "Dr. Fritzliebe",
                    [0x847689782b9e0876UL] = "¡Cierren la puerta!",
                    [0x88760e3fa2926f3bUL] = "Americano. ¿Y usted, señorita? ¿Rusa, verdad?",
                    [0x8aee3d0b75a5fd3dUL] = "¡Ahí vienen!",
                    [0x8b1f68cf084d7b7bUL] = "¡Abran esa puerta! ¡Prueben la válvula!",
                    [0x8c2fe2a554a2db50UL] = "Urrrgh...",
                    [0x8ea04a9910d7a8abUL] = "¡¡¡RARRRRRRRRH!!!",
                    [0x8f2186080cfb3f18UL] = "¿Qué demonios me hicieron? ¡Siento que podría levantar un camión!",
                    [0x8fd83fc67fe9b793UL] = "Uy. ¿Qué es ese ruido?",
                    [0x9401ef9bc24c4cd4UL] = "¡Cuidado!",
                    [0x94d799231e2ef14cUL] = "¿Alguien tiene una granada?",
                    [0x94f3da435499cfefUL] = "¿Qué sabes de ellos?",
                    [0x99a4111e7666a3b8UL] = "¡Le preguntaré al científico en jefe mientras le aprieto su cuello nazi!",
                    [0x99f616758a5083a7UL] = "¡Ja! ¡Ya veremos!",
                    [0x99fb968505880e5fUL] = "Eso estuvo... duro. ¿Cuánto tiempo estuve inconsciente?",
                    [0x9a5fd0af138056fbUL] = "¡La puerta está abierta! ¡Tengo que entrar!",
                    [0x9e76ca2b1b590009UL] = "¡Hm! ¿El Kriegbär se ha escapado? Eso no augura nada bueno para ustedes, mis Lieblings.",
                    [0x9f031c4016299ccaUL] = "Si lo que he oído es cierto, puede que sean justo lo que necesitamos para ganar esta guerra...",
                    [0xa00cfe8c3f89d67eUL] = "Oficial SS",
                    [0xa0af763a31a874f1UL] = "Ahí va, chicos. Misión cumplida.",
                    [0xa13de05f82031646UL] = "Mejor lanzo una granada dentro del cañón.",
                    [0xa31a212dbae8c699UL] = "Cañones... ese doctor loco mencionó algo así como... un sistema antiaéreo. Si destruimos los cañones, quizá los bombarderos tengan una oportunidad...",
                    [0xa5038973fe6e676fUL] = "¡Tenemos que pasar esa puerta! ¡Prueben la válvula!",
                    [0xa53c1bbac592b0ddUL] = "¿Qué te hace decir eso?",
                    [0xa5ddb36f88d25428UL] = "Caray. Y yo que pensaba que los nazis comunes ya eran bastante malos.",
                    [0xa8977cac5639d608UL] = "...es Stave Rygur.",
                    [0xa8f097a94f7c134bUL] = "Mon dieu... ¿Qué demonios está pasando?",
                    [0xa9f7bfcee3dbb725UL] = "Enchanté, madame. Marcel Marie, Resistencia francesa.",
                    [0xab049533d0c82bb7UL] = "¡HEIL HITLER!",
                    [0xae93e41c0f96c2f2UL] = "Eso estuvo... duro. Pero aún no estoy muerto.",
                    [0xafae01eb3b81b195UL] = "Yo tampoco. Pero ¿dónde estamos...? ¿Cómo...?",
                    [0xb20893ef0887644aUL] = "¡Necios insolentes!",
                    [0xb42de862d877563fUL] = "Sgto. Irina Petrovska. Rusia.",
                    [0xb4cad497e51b717eUL] = "¿Dónde demonios...?",
                    [0xb9ceea0299f8a5a8UL] = "Peleaste bien allá atrás. Soy la Sgto. Irina Petrovska.",
                    [0xbb68de4374c81459UL] = "¡Abran esa puerta! ¡Prueben la válvula!",
                    [0xbd1c5e1a96342b3dUL] = "Demonios...",
                    [0xbe70d440b4b5571fUL] = "¡Mueran ahora!",
                    [0xc016c3d70a417178UL] = "¡Hm! ¿El Kriegbär se ha escapado? Eso no augura nada bueno para ti, amigo mío.",
                    [0xc14605f3173c5701UL] = "¡Rápido, por la puerta!",
                    [0xc484c3a4e147841dUL] = "¡Destruyan los cañones lanzando una granada dentro del cañón!",
                    [0xc7a4c28cb3b0df2eUL] = "¡Es hora de que rectifique ese error! Los desarmaré, empezaré de nuevo. Y el siguiente modelo será mejor. ¡OBEDECERÁN!",
                    [0xcb16811cd0e0063bUL] = "¡La puerta está cerrada! ¡No pueden entrar!",
                    [0xcc046486f027544dUL] = "¡Puerta cerrada!",
                    [0xcdd6675c1b199d86UL] = "¡Alguien está saliendo, señor!",
                    [0xce98a25209ef4e14UL] = "Coro",
                    [0xd087f6ba2b5d6b23UL] = "¡Que vengan las bombas! Aunque preferiría estar bajo tierra primero...",
                    [0xd1463da2413c9109UL] = "Castillo Sonnenfreude\nEn algún lugar de Austria\nDiciembre de 1943",
                    [0xd14f14ca876a1d5dUL] = "¡Ah, hijos míos! Han llegado tan lejos. Cómo me enorgullece. ¡Son realmente mi mayor TRIUNFO científico!",
                    [0xd1b4616f438e655dUL] = "Me siento... diferente. Más fuerte... ¿Qué demonios me hizo ese doctor loco?",
                    [0xd68a2dffd8d668dbUL] = "¡Ríndete, Fritzliebe! ¡Hemos destruido todos tus juguetes!",
                    [0xd8d790471d470c70UL] = "¡Se acabaron los cañones! ¡Los bombarderos ya pueden pasar!",
                    [0xdac42869d912eb36UL] = "¡Una granada en la garganta acaba con lo que sea!",
                    [0xdb8b3082456b7900UL] = "¡Cierren la puerta! ¡Eso los dejará fuera!",
                    [0xdbf2762283f9e73dUL] = "¡No tema! ¡Mi sistema antiaéreo se encargará de ellos en breve!",
                    [0xdc82a7ffb1baa7ccUL] = "Ni de chiste los bombarderos van a pasar con ESE fuego. No me gusta... pero veamos esos cañones.",
                    [0xe0dc4f2018950395UL] = "¿Hay un ataque aéreo en curso? Eso podría darme una oportunidad...",
                    [0xe1255d1cad20be07UL] = "¡¡¡Argh!!!",
                    [0xe19a4fb2cdb8fac1UL] = "¡Vamos, vamos! ¡La puerta está abierta!",
                    [0xe1e5058b90f74f7eUL] = "Permítanme presentarme... Marcel Marie, Resistencia francesa.",
                    [0xe734550562021d44UL] = "Me alegra que estemos del mismo lado. Soy Lt. Eugene McBride, ejército de EE. UU.",
                    [0xe781e161ece2e307UL] = "Me temo que nuestras posibilidades son bastante escasas.",
                    [0xe81aa415f0160f15UL] = "Aun así... estos viejos sótanos están en malas condiciones. ¡¡Raus!!",
                    [0xe924a28306aaa508UL] = "¡Funciona! ¡La puerta está cerrada!",
                    [0xed43510f839db819UL] = "¡Vienen hacia acá!",
                    [0xf0a9d696b19d91f3UL] = "Necesito una granada de mano...",
                    [0xf280dd5dda80bf7aUL] = "Sgto. Irina Petrovska, Ejército Rojo.",
                    [0xf499c110f6abe42bUL] = "Son mi mayor triunfo... ¡Pero también mi mayor error!",
                    [0xf682ec890cd8dea9UL] = "¡Verdammt! ¿Dónde está el maldito ascensor?",
                    [0xfb245b1f4cb7b6b8UL] = "...Más enojado.",
                    [0xfc770e6bb0d4ee7bUL] = "¡Shh! Creí haber oído algo...",
                },
                ["es-ES"] = new()
                {
                    [0x00c828920feb30a9UL] = "No pareces nazi, ¿cómo demonios saliste vivo?",
                    [0x00f894c753526ecaUL] = "Ah, hijos míos... habéis matado al pobre Kriegbär #2.",
                    [0x04ea71f543f7a181UL] = "¡Pero también mi mayor ERROR! ¡Es hora de rectificarlo! ¡Frau Sturmbannführer! ¡Traédmelos!",
                    [0x068bd1e0ac21a69eUL] = "Oh, claro... Nazis.",
                    [0x130cb8e004b1746fUL] = "O Tannenbaum, o Tannenbaum,\nwie treu sind deine Blätter!",
                    [0x136b271625dfa814UL] = "No. Sigamos adelante. Este castillo aún no está muerto.",
                    [0x16c94d4cdbfbd83aUL] = "¡Nein, nein, nein! ¡Otra vez tarde!",
                    [0x17594f4811a66fb1UL] = "Da... ¿dónde estamos?",
                    [0x18ee39dc7f64b7acUL] = "El símbolo del Sol de Seis Lados... estamos en manos de las SSS.",
                    [0x18fcc16fbb3dd6a8UL] = "No lo sé, pero voy a averiguarlo.",
                    [0x19e22d8dbc2511f3UL] = "¡Destruid los cañones! ¡Una granada en el cañón debería bastar!",
                    [0x1a5a9e011c4e5fe2UL] = "Lt. Eugene McBride, ejército de EE. UU....",
                    [0x1adf386486cd3f55UL] = "¡Hay que destruir esos cañones!",
                    [0x1b7ada164ffa40e3UL] = "¡Ese no es un nombre de verdad!",
                    [0x1c07e9eecf9d03ecUL] = "Creo que pretendían convertir a seres humanos en armas.",
                    [0x1ffaba68dba5eb7dUL] = "No importa, me lo cuentas luego. ¡Mis órdenes son sacaros de aquí cagando leches!",
                    [0x2146921baf773954UL] = "No lo sé, pero yo no me quedo aquí.",
                    [0x21cbcb67482f6dd3UL] = "Lt. Eugene McBride. Americano.",
                    [0x21faa64bab773212UL] = "Me siento... distinto. Más fuerte... más resistente.",
                    [0x26229618cf6b2706UL] = "Con calma ahora...",
                    [0x263ef99ee3dd3bdfUL] = "(¡Y pronto el propio Führer se acobardará ante Fritzliebe! ¡Ja-ja!)",
                    [0x266ca9e1237fd940UL] = "¿Qué es eso, doctor?",
                    [0x29b3a84d1bd5b60fUL] = "Hay nieve... pero no hay sol. Debe ser de noche fuera.",
                    [0x29c8a93ca01dfe83UL] = "Da. Recuerdo que me capturaron... me torturaron...",
                    [0x2d7f0f37395c44b3UL] = "¿Qué eres? ¿Alemán? ¿Británico?",
                    [0x2e43b75b784acb3aUL] = "No lo sé, pero no pienso volver a uno de esos tanques.",
                    [0x310d3b80502503b9UL] = "¡Entrad! ¡Rápido!",
                    [0x33dba133326568c5UL] = "¡Una granada en el cañón debería bastar!",
                    [0x34e13ec981301157UL] = "¡No podréis pasar ahora, malditos bastardos!",
                    [0x3702712331c60bbbUL] = "¡NEIN! ¡Du darfst den Weihnachtsbaum nicht zerstören!",
                    [0x37d4da79f91ea69dUL] = "...¡pero también tengo muchos avances MECHANISCHE que mostraros!",
                    [0x39108d3782fcc184UL] = "¡Por AHÍ no pueden pasar!",
                    [0x399d69478283bf0aUL] = "¡Ah, pobre Kriegbär #2! Era una de mis criaturas favoritas. Oh, bueno... ¡Admito la derrota! ¡Entrad y discutamos los términos de mi rendición!",
                    [0x39b11fc2eb9591f7UL] = "¿Esperamos aquí? Quizá vengan a rescatarnos.",
                    [0x3acef01069bf7698UL] = "¡Buen trabajo! No sé vosotros, pero prefiero estar bajo tierra.",
                    [0x3bb78c987c37ef80UL] = "Supongo que guardaron nuestra ropa vieja.",
                    [0x3c42fab09bee3aceUL] = "¡Cerrad esa puerta!",
                    [0x3d0b9534cd0767daUL] = "Du grünst nicht nur zur Sommerzeit,\nNein auch im Winter, wenn es schneit!",
                    [0x3d211a9f797e8abcUL] = "¡Maldito ruido! ¡Hay que acabar con esos cañones!",
                    [0x3f1367c4cc04d1ceUL] = "Urrrgh... mi cabeza...",
                    [0x3f57a8067643aaf1UL] = "¡¡¡Attentaten!!!",
                    [0x3f7b9829b86ec16dUL] = "¿Hay un ataque aéreo en marcha? Podría ser nuestra oportunidad de escapar...",
                    [0x421bf0c8717484ceUL] = "Una sociedad secreta dentro del Reich. Investigación secreta: armas, bioingeniería, ocultismo...",
                    [0x431937b187f1272fUL] = "Esa no es una bandera nazi normal. ¿Qué es esto?",
                    [0x455df089e85d4bebUL] = "¡Queda un cañón!",
                    [0x46ee9a6b83e2eaf5UL] = "¡Otra vez, desde arriba! ¡Y con más sentimiento esta vez!",
                    [0x486ff7ab0719fa17UL] = "¡Se lo preguntaré a ese científico que nos torturó... mientras le aprieto su cuello nazi!",
                    [0x496af45538186714UL] = "Extraño... ¡Nunca fui un luchador, pero ahora me siento imparable!",
                    [0x4b729df370265d0aUL] = "¡Pero también mi mayor ERROR! ¡Es hora de rectificarlo! ¡Frau Sturmbannführer! ¡Traedme al espécimen!",
                    [0x4babb86958a61d60UL] = "Yo también me siento en excelente forma física...",
                    [0x4bb1cb28780395f0UL] = "¡Funciona! ¡Faltan dos cañones!",
                    [0x4bd699fb74d17592UL] = "¡Das ist unfair!",
                    [0x4c7ea1bb00311aacUL] = "¡Tenemos que volarlos desde DENTRO!",
                    [0x50b1af47c674d007UL] = "Buenas noches, Dr. Fritzliebe! ¿Cómo va el proyecto Überkämpfer?",
                    [0x519c7a5ff358e4c4UL] = "Solo que son nazis. De los peores.",
                    [0x53192b0aa2e141ffUL] = "¡Probad a lanzar las granadas DENTRO de los cañones!",
                    [0x537f76c41d40d6cbUL] = "¡Mein Gott! ¡Detenedlos!",
