                    [0x593a7092b87f94baUL] = "¡Verdammt! ¡Un ataque aéreo aliado!",
                    [0x5b1a6ebf6ea7465eUL] = "¡Excelentemente, Herr Sturmbannführer! ¡Los prisioneros están respondiendo extremadamente bien a la fórmula! ¡Pronto el Führer tendrá su ejército imparable!",
                    [0x5bc1e6c5102e900fUL] = "Supongo que deberían habérselo pensado dos veces.",
                    [0x5eae866eb3ba9881UL] = "¡La puerta está abierta! ¡Entrad!",
