                    [0x62840e40cb928a25UL] = "Deben ser todas esas vitaminas en las que nos hacían nadar...",
                    [0x62f96b2e5c9ddd1eUL] = "¡Nazis!",
                    [0x6330a806d40f3cdcUL] = "¡¡¡HNNNARRRRRRRHHH!!!",
                    [0x6361c1d29798d152UL] = "De acuerdo. Entonces ya sabes a qué nos enfrentamos.",
                    [0x63b1bc586efa968cUL] = "BIOCHEMIE es mi especialidad, es cierto...",
                    [0x64edc3775470fac9UL] = "¡No me cogeréis vivo, demonios!",
                    [0x6912caa2276adbb7UL] = "¡¿Qué demonios ha sido eso?!",
                    [0x697cde99d527e9a5UL] = "Estos nazis no dan mucha guerra, ¿eh?",
                    [0x6dc8d99282b85e62UL] = "¿Yo? Mi nombre...",
                    [0x6e14c9685d7edd2bUL] = "¡Tengo que abrir esa puerta! Esa válvula parece la correcta...",
                    [0x6ec71031388eec00UL] = "¡¿Y ahora cómo demonios cierro la puerta?!",
                    [0x6f47bc553da9b8e5UL] = "*cof* ¡Arrrrrgh... Schweinhunden! ¡Me habéis matado... pero no escaparéis vivos de aquí!",
                    [0x6fa7b2bcfe086ad3UL] = "¿Hay alguna forma de subir a la superficie?",
