                    [0x700f189385300980UL] = "Una granada por el cañón debería silenciar esos cañones...",
                    [0x74e42ee050e494aeUL] = "¿Y tú, tipo duro? ¿Cómo te llaman?",
                    [0x774336bb6f239c56UL] = "Tú mismo.",
                    [0x7853d8633fd979b0UL] = "¡Probad esa válvula roja!",
                    [0x7c20e94fb4650a48UL] = "Kriegbär #2",
                    [0x7c9ab3548d1d56fdUL] = "Marcel Marie, Resistencia francesa.",
                    [0x7ec8470fa0f88a10UL] = "¡Shhh! ¡Escuchad! ¿Qué es eso?",
                    [0x81e08fcf3b26b2c0UL] = "¡Ah, hijo mío! ¡Has llegado tan lejos! ¡Qué orgulloso estoy! ¡Eres realmente mi mayor TRIUNFO científico!",
                    [0x829963066c214aaaUL] = "Dr. Fritzliebe",
                    [0x847689782b9e0876UL] = "¡Cerrad la puerta!",
                    [0x88760e3fa2926f3bUL] = "Americano. ¿Y tú, guapa? Rusa, ¿verdad?",
                    [0x8aee3d0b75a5fd3dUL] = "¡Ya vienen!",
                    [0x8b1f68cf084d7b7bUL] = "¡Abrid esa puerta! ¡Probad la válvula!",
                    [0x8c2fe2a554a2db50UL] = "Urrrgh...",
                    [0x8ea04a9910d7a8abUL] = "¡¡¡RARRRRRRRRH!!!",
                    [0x8f2186080cfb3f18UL] = "¿Qué demonios me hicieron? ¡Siento que podría levantar un camión!",
                    [0x8fd83fc67fe9b793UL] = "Vaya. ¿Qué es ese ruido?",
                    [0x9401ef9bc24c4cd4UL] = "¡Cuidado!",
                    [0x94d799231e2ef14cUL] = "¿Alguien tiene una granada?",
                    [0x94f3da435499cfefUL] = "¿Qué sabes de ellos?",
                    [0x99a4111e7666a3b8UL] = "¡Se lo preguntaré al científico jefe mientras le aprieto su cuello nazi!",
                    [0x99f616758a5083a7UL] = "¡Ja! ¡Ya veremos!",
                    [0x99fb968505880e5fUL] = "Eso... fue duro. ¿Cuánto tiempo estuve inconsciente?",
                    [0x9a5fd0af138056fbUL] = "¡La puerta está abierta! ¡Hay que entrar!",
                    [0x9e76ca2b1b590009UL] = "¡Hm! ¿El Kriegbär ha escapado? ¡Eso no augura nada bueno para ti, Lieblings!",
                    [0x9f031c4016299ccaUL] = "Si lo que he oído es cierto, podríais ser justo lo que necesitamos para ganar esta guerra...",
                    [0xa00cfe8c3f89d67eUL] = "Oficial SS",
                    [0xa0af763a31a874f1UL] = "Ahí va, chicos. Misión cumplida.",
                    [0xa13de05f82031646UL] = "Mejor lanzar una granada por el cañón.",
                    [0xa31a212dbae8c699UL] = "Cañones... ese médico loco mencionó una especie de... sistema antiaéreo. Si destruimos los cañones, quizá los bombarderos tengan una oportunidad...",
                    [0xa5038973fe6e676fUL] = "¡Tenemos que cruzar esa puerta! ¡Probad la válvula!",
                    [0xa53c1bbac592b0ddUL] = "¿Qué te hace decir eso?",
                    [0xa5ddb36f88d25428UL] = "Vaya. Y yo que pensaba que los nazis normales ya eran bastante malos.",
                    [0xa8977cac5639d608UL] = "...es Stave Rygur.",
                    [0xa8f097a94f7c134bUL] = "Mon dieu... ¿Qué demonios está pasando?",
                    [0xa9f7bfcee3dbb725UL] = "Enchanté, madame. Marcel Marie, Resistencia francesa.",
                    [0xab049533d0c82bb7UL] = "¡HEIL HITLER!",
                    [0xae93e41c0f96c2f2UL] = "Eso... fue duro. Pero aún no estoy muerto.",
                    [0xafae01eb3b81b195UL] = "Yo tampoco. Pero ¿dónde estamos...? ¿Cómo...?",
                    [0xb20893ef0887644aUL] = "¡Insolentes!",
                    [0xb42de862d877563fUL] = "Sgto. Irina Petrovska. Rusia.",
                    [0xb4cad497e51b717eUL] = "¿Dónde demonios...?",
                    [0xb9ceea0299f8a5a8UL] = "Luchaste bien ahí atrás. Soy la Sgto. Irina Petrovska.",
                    [0xbb68de4374c81459UL] = "¡Abrid esa puerta! ¡Probad la válvula!",
                    [0xbd1c5e1a96342b3dUL] = "Maldita sea...",
                    [0xbe70d440b4b5571fUL] = "¡Muere ahora!",
                    [0xc016c3d70a417178UL] = "¡Hm! ¿El Kriegbär ha escapado? ¡Eso no augura nada bueno para ti, amigo mío!",
                    [0xc14605f3173c5701UL] = "¡Rápido, por la puerta!",
                    [0xc484c3a4e147841dUL] = "¡Destruid los cañones lanzando una granada por el cañón!",
                    [0xc7a4c28cb3b0df2eUL] = "¡Es hora de rectificar ese error! ¡Os desmontaré y empezaré de nuevo. Y el próximo modelo será mejor. ¡OBEDECERÁ!",
                    [0xcb16811cd0e0063bUL] = "¡La puerta está cerrada! ¡No pueden entrar!",
                    [0xcc046486f027544dUL] = "¡Puerta cerrada!",
                    [0xcdd6675c1b199d86UL] = "¡Alguien sale, señor!",
                    [0xce98a25209ef4e14UL] = "Coro",
                    [0xd087f6ba2b5d6b23UL] = "¡Que caigan las bombas! Aunque prefiero estar bajo tierra primero...",
                    [0xd1463da2413c9109UL] = "Castillo Sonnenfreude\nEn algún lugar de Austria\nDiciembre de 1943",
                    [0xd14f14ca876a1d5dUL] = "¡Ah, niños! ¡Habéis llegado tan lejos! ¡Qué orgulloso estoy! ¡Sois realmente mi mayor TRIUNFO científico!",
                    [0xd1b4616f438e655dUL] = "Me siento... distinto. Más fuerte... ¿Qué demonios me hizo ese médico loco?",
                    [0xd68a2dffd8d668dbUL] = "¡Ríndete, Fritzliebe! ¡Hemos destruido todos tus juguetes!",
                    [0xd8d790471d470c70UL] = "¡Eso son todos los cañones! ¡Los bombarderos ya pueden pasar!",
                    [0xdac42869d912eb36UL] = "¡Una granada en la boca acaba con cualquier cosa!",
                    [0xdb8b3082456b7900UL] = "¡Cerrad la puerta! ¡Eso los mantendrá fuera!",
                    [0xdbf2762283f9e73dUL] = "¡No temáis! ¡Mi sistema antiaéreo se encargará de ellos en breve!",
                    [0xdc82a7ffb1baa7ccUL] = "Ni de broma atraviesan los bombarderos ESE fuego. No me gusta... pero ocupémonos de esos cañones.",
                    [0xe0dc4f2018950395UL] = "¿Hay un ataque aéreo en marcha? Podría darme una oportunidad...",
                    [0xe1255d1cad20be07UL] = "¡Argh!!!",
                    [0xe19a4fb2cdb8fac1UL] = "¡Vamos, vamos! ¡La puerta está abierta!",
                    [0xe1e5058b90f74f7eUL] = "Permitidme que me presente... Marcel Marie, Resistencia francesa.",
                    [0xe734550562021d44UL] = "Me alegro de que estemos del mismo lado. Soy el Lt. Eugene McBride, ejército de EE. UU.",
                    [0xe781e161ece2e307UL] = "Me temo que nuestras posibilidades son escasas.",
                    [0xe81aa415f0160f15UL] = "Aun así... estos viejos sótanos están en mal estado. ¡¡Raus!!",
                    [0xe924a28306aaa508UL] = "¡Funciona! ¡La puerta está cerrada!",
                    [0xed43510f839db819UL] = "¡Ahí vienen!",
                    [0xf0a9d696b19d91f3UL] = "Necesito una granada de mano...",
                    [0xf280dd5dda80bf7aUL] = "Sgto. Irina Petrovska, Ejército Rojo.",
                    [0xf499c110f6abe42bUL] = "¡Sois mi mayor triunfo... pero también mi mayor error!",
                    [0xf682ec890cd8dea9UL] = "¡Verdammt! ¿Wo ist der Aufzug?",
                    [0xfb245b1f4cb7b6b8UL] = "...Más enfadado.",
                    [0xfc770e6bb0d4ee7bUL] = "¡Shh! Creí haber oído algo...",
                },
                ["pt-BR"] = new()
                {
                    [0x00c828920feb30a9UL] = "Você não parece nazista – como diabos saiu vivo?",
                    [0x00f894c753526ecaUL] = "Ah, meus filhos... vocês mataram o pobre Kriegbär #2.",
                    [0x04ea71f543f7a181UL] = "Mas também meu maior ERRO! É hora de corrigir! Frau Sturmbannführer! Tragam-nos para mim!",
                    [0x068bd1e0ac21a69eUL] = "Ah, é... Nazistas.",
                    [0x130cb8e004b1746fUL] = "O Tannenbaum, o Tannenbaum,\nwie treu sind deine Blätter!",
                    [0x136b271625dfa814UL] = "Não. Vamos em frente. Este castelo ainda não morreu.",
                    [0x16c94d4cdbfbd83aUL] = "Nein, nein, nein! Atrasado de novo!",
                    [0x17594f4811a66fb1UL] = "Da... onde estamos?",
                    [0x18ee39dc7f64b7acUL] = "O símbolo do Sol de Seis Lados... então estamos nas mãos da SSS.",
                    [0x18fcc16fbb3dd6a8UL] = "Não sei, mas vou descobrir.",
                    [0x19e22d8dbc2511f3UL] = "Destrua os canhões! Uma granada no cano deve dar conta.",
                    [0x1a5a9e011c4e5fe2UL] = "Lt. Eugene McBride, Exército dos EUA...",
                    [0x1adf386486cd3f55UL] = "Tenho que destruir esses canhões!",
                    [0x1b7ada164ffa40e3UL] = "Esse não é um nome de verdade!",
                    [0x1c07e9eecf9d03ecUL] = "Acho que eles queriam transformar gente em arma.",
                    [0x1ffaba68dba5eb7dUL] = "Deixa pra lá, me conta depois. Minha ordem é tirar vocês daqui o mais rápido possível!",
                    [0x2146921baf773954UL] = "Não sei, mas não vou ficar por aqui.",
                    [0x21cbcb67482f6dd3UL] = "Lt. Eugene McBride. Americano.",
                    [0x21faa64bab773212UL] = "Me sinto... diferente. Mais forte... mais resistente.",
                    [0x26229618cf6b2706UL] = "Devagar e com calma agora...",
                    [0x263ef99ee3dd3bdfUL] = "(E logo o próprio Führer vai se acovardar diante de Fritzliebe! Ha-ha!)",
                    [0x266ca9e1237fd940UL] = "Como disse, doutor?",
                    [0x29b3a84d1bd5b60fUL] = "Tem neve... mas sem sol. Deve ser noite lá fora.",
                    [0x29c8a93ca01dfe83UL] = "Da. Lembro de ter sido capturada... torturada...",
                    [0x2d7f0f37395c44b3UL] = "O que você é? Alemão? Britânico?",
                    [0x2e43b75b784acb3aUL] = "Não sei, mas não vou voltar pra um daqueles tanques.",
                    [0x310d3b80502503b9UL] = "Entrem! Rápido!",
                    [0x33dba133326568c5UL] = "Uma granada no cano deve resolver!",
                    [0x34e13ec981301157UL] = "Vocês não passam agora, seus canalhas podres!",
                    [0x3702712331c60bbbUL] = "NEIN! Du darfst den Weihnachtsbaum nicht zerstören!",
                    [0x37d4da79f91ea69dUL] = "...mas também tenho muitos avanços MECÂNICOS para mostrar!",
                    [0x39108d3782fcc184UL] = "Eles não passam por ESSA!",
                    [0x399d69478283bf0aUL] = "Ah, pobre Kriegbär #2! Era uma de minhas criaturas favoritas. Bem... Admito a derrota. Entrem e discutamos a rendição!",
                    [0x39b11fc2eb9591f7UL] = "Devemos esperar aqui? Talvez nos resgatem.",
                    [0x3acef01069bf7698UL] = "Bom trabalho! Não sei vocês, mas eu quero ir pro subsolo.",
                    [0x3bb78c987c37ef80UL] = "Acho que guardaram nossas roupas velhas.",
                    [0x3c42fab09bee3aceUL] = "Feche essa porta!",
                    [0x3d0b9534cd0767daUL] = "Du grünst nicht nur zur Sommerzeit,\nNein auch im Winter, wenn es schneit!",
                    [0x3d211a9f797e8abcUL] = "Maldito barulho! Tenho que calar esses canhões!",
                    [0x3f1367c4cc04d1ceUL] = "Urrrgh... minha cabeça...",
                    [0x3f57a8067643aaf1UL] = "Attentaten!!!",
                    [0x3f7b9829b86ec16dUL] = "Tem um ataque aéreo rolando? Pode ser nossa chance de fugir...",
                    [0x421bf0c8717484ceUL] = "Uma sociedade secreta dentro do Reich. Pesquisa secreta - armas, bioengenharia, ocultismo...",
                    [0x431937b187f1272fUL] = "Essa não é uma bandeira nazista comum. O que é isso?",
                    [0x455df089e85d4bebUL] = "Falta um canhão!",
                    [0x46ee9a6b83e2eaf5UL] = "De novo, do começo! E com mais sentimento desta vez!",
                    [0x486ff7ab0719fa17UL] = "Vou perguntar àquele cientista que nos torturou... enquanto espremo o pescoço nazista dele!",
                    [0x496af45538186714UL] = "Estranho... nunca fui de lutar, mas agora me sinto imparável!",
                    [0x4b729df370265d0aUL] = "Mas também meu maior ERRO! É hora de corrigir! Frau Sturmbannführer! Traga-me o espécime!",
                    [0x4babb86958a61d60UL] = "Eu também me sinto em excelente forma física...",
                    [0x4bb1cb28780395f0UL] = "Funcionou! Faltam dois canhões!",
                    [0x4bd699fb74d17592UL] = "Das ist unfair!",
                    [0x4c7ea1bb00311aacUL] = "Temos que explodi-los por DENTRO!",
                    [0x50b1af47c674d007UL] = "Boa noite, Dr. Fritzliebe! Como vai o projeto Überkämpfer?",
                    [0x519c7a5ff358e4c4UL] = "Só que são nazistas. Do pior tipo.",
                    [0x53192b0aa2e141ffUL] = "Tente jogar as granadas DENTRO dos canhões!",
                    [0x537f76c41d40d6cbUL] = "Mein Gott! Parem-nos!",
                    [0x5712908027cd5023UL] = "Vocês não parecem nazistas – como diabos saíram vivos?",
                    [0x5767d170e5d4e177UL] = "Eu disse, HEIL HITLER!",
                    [0x57ed6136f8836ba7UL] = "Segunda válvula! Feche a porta!",
                    [0x593a7092b87f94baUL] = "Verdammt! Um ataque aéreo Aliado!",
                    [0x5b1a6ebf6ea7465eUL] = "Excelentemente, Herr Sturmbannführer! Os prisioneiros estão respondendo muito bem à fórmula! Em breve o Führer terá seu exército imparável!",
                    [0x5bc1e6c5102e900fUL] = "Acho que deviam ter pensado duas vezes.",
                    [0x5eae866eb3ba9881UL] = "A porta está aberta! Entrem!",
                    [0x5f9ed0775cd2d462UL] = "Chamam de 'Die Sechs-Seitige Sonne'. É má notícia.",
                    [0x612c5f5890b06a4dUL] = "Aaaaaaaah!",
                    [0x6225ce9cb05fbf29UL] = "O que você sabe sobre a SSS?",
                    [0x62840e40cb928a25UL] = "Devem ser todas aquelas vitaminas em que nadamos...",
                    [0x62f96b2e5c9ddd1eUL] = "Nazistas!",
                    [0x6330a806d40f3cdcUL] = "HNNNARRRRRRRHHH!",
                    [0x6361c1d29798d152UL] = "Justo. Então você tem ideia do que enfrentamos.",
                    [0x63b1bc586efa968cUL] = "BIOQUÍMICA é minha especialidade, é verdade...",
                    [0x64edc3775470fac9UL] = "Vocês não vão me pegar vivo, seus diabos!",
                    [0x6912caa2276adbb7UL] = "Que diabos foi isso!",
                    [0x697cde99d527e9a5UL] = "Esses nazistas não lutam muito bem, né?",
                    [0x6dc8d99282b85e62UL] = "Eu? Meu nome...",
                    [0x6e14c9685d7edd2bUL] = "Tenho que abrir essa porta! Aquela válvula parece certa...",
                    [0x6ec71031388eec00UL] = "Agora como diabos fecho a porta!",
                    [0x6f47bc553da9b8e5UL] = "*tosse* Arrrrgh... Schweinhunden! Vocês me mataram... mas não sairão daqui vivos!",
                    [0x6fa7b2bcfe086ad3UL] = "Tem um caminho até a superfície?",
                    [0x6ff7c93100bf1649UL] = "Vou ter que desmontar vocês e começar de novo. E desta vez serão perfeitos!",
                    [0x700f189385300980UL] = "Uma granada no cano deve calar esses canhões...",
                    [0x74e42ee050e494aeUL] = "E você, durão? Como te chamam?",
                    [0x774336bb6f239c56UL] = "Como quiser.",
                    [0x7853d8633fd979b0UL] = "Tente aquela válvula vermelha!",
                    [0x7c20e94fb4650a48UL] = "Kriegbär #2",
                    [0x7c9ab3548d1d56fdUL] = "Marcel Marie, Resistência Francesa.",
                    [0x7ec8470fa0f88a10UL] = "Shhh! Escuta! O que é isso?",
                    [0x81e08fcf3b26b2c0UL] = "Ah, meu filho! Você chegou tão longe. Como estou orgulhoso! Você realmente é meu maior TRIUNFO científico!",
                    [0x829963066c214aaaUL] = "Dr. Fritzliebe",
                    [0x847689782b9e0876UL] = "Feche a porta!",
                    [0x88760e3fa2926f3bUL] = "Americano. E você, moça? Russa, certo?",
                    [0x8aee3d0b75a5fd3dUL] = "Lá vêm eles!",
                    [0x8b1f68cf084d7b7bUL] = "Abra essa porta! Tente a válvula!",
                    [0x8c2fe2a554a2db50UL] = "Urrrgh...",
                    [0x8ea04a9910d7a8abUL] = "RARRRRRRRRH!!",
                    [0x8f2186080cfb3f18UL] = "Que diabos fizeram comigo? Sinto que consigo levantar um caminhão!",
                    [0x8fd83fc67fe9b793UL] = "Uh-oh. Que barulho é esse?",
                    [0x9401ef9bc24c4cd4UL] = "Cuidado!",
                    [0x94d799231e2ef14cUL] = "Alguém tem uma granada?",
                    [0x94f3da435499cfefUL] = "O que você sabe sobre eles?",
                    [0x99a4111e7666a3b8UL] = "Vou perguntar ao cientista-chefe enquanto espremo o pescoço nazista dele!",
                    [0x99f616758a5083a7UL] = "Ha! Veremos!",
                    [0x99fb968505880e5fUL] = "Isso foi... bruto. Quanto tempo fiquei desacordado?",
                    [0x9a5fd0af138056fbUL] = "A porta abriu! Tenho que entrar!",
                    [0x9e76ca2b1b590009UL] = "Hm! O Kriegbär escapou? Mau presságio para você, querido!",
                    [0x9f031c4016299ccaUL] = "Se o que ouvi é verdade, vocês podem ser exatamente o que precisamos para vencer esta guerra...",
                    [0xa00cfe8c3f89d67eUL] = "Oficial da SS",
                    [0xa0af763a31a874f1UL] = "Lá vai ela, rapazes. Missão cumprida.",
                    [0xa13de05f82031646UL] = "Melhor jogar uma granada no cano.",
                    [0xa31a212dbae8c699UL] = "Canhões... aquele médico maluco falou de um... sistema antiaéreo. Se os canhões caírem, os bombardeiros têm chance...",
                    [0xa5038973fe6e676fUL] = "Precisamos passar por essa porta! Tente a válvula!",
                    [0xa53c1bbac592b0ddUL] = "O que te faz dizer isso?",
                    [0xa5ddb36f88d25428UL] = "Caramba. E eu achando que nazista comum já era ruim o bastante.",
                    [0xa8977cac5639d608UL] = "...é Stave Rygur.",
                    [0xa8f097a94f7c134bUL] = "Mon dieu... Que diabos está acontecendo?",
                    [0xa9f7bfcee3dbb725UL] = "Enchanté, madame. Marcel Marie, Resistência Francesa.",
                    [0xab049533d0c82bb7UL] = "HEIL HITLER!",
                    [0xae93e41c0f96c2f2UL] = "Isso foi... bruto. Mas ainda não morri.",
                    [0xafae01eb3b81b195UL] = "Eu também. Mas onde estamos... Como...?",
                    [0xb20893ef0887644aUL] = "Tolos insolentes!",
                    [0xb42de862d877563fUL] = "Sgt. Irina Petrovska. Rússia.",
                    [0xb4cad497e51b717eUL] = "Onde diabos...?",
                    [0xb9ceea0299f8a5a8UL] = "Você lutou bem lá atrás. Sou a Sgt. Irina Petrovska.",
                    [0xbb68de4374c81459UL] = "Abra essa porta! Tente a válvula!",
                    [0xbd1c5e1a96342b3dUL] = "Inferno...",
                    [0xbe70d440b4b5571fUL] = "Morram agora!",
                    [0xc016c3d70a417178UL] = "Hm! O Kriegbär escapou? Isso é mau presságio para você, meu amigo!",
                    [0xc14605f3173c5701UL] = "Rápido, pela porta!",
                    [0xc484c3a4e147841dUL] = "Destrua os canhões jogando uma granada no cano!",
                    [0xc7a4c28cb3b0df2eUL] = "É hora de corrigir esse erro! Vou desmontar vocês e começar de novo. E o próximo modelo será melhor. Ele OBEDECERÁ.",
                    [0xcb16811cd0e0063bUL] = "A porta fechou! Eles não podem entrar!",
                    [0xcc046486f027544dUL] = "Porta fechada!",
                    [0xcdd6675c1b199d86UL] = "Alguém está saindo, senhor!",
                    [0xce98a25209ef4e14UL] = "Coro",
                    [0xd087f6ba2b5d6b23UL] = "Mandem as bombas! Mas eu queria estar no subsolo antes...",
                    [0xd1463da2413c9109UL] = "Castelo Sonnenfreude\nEm algum lugar da Áustria\nDezembro de 1943",
                    [0xd14f14ca876a1d5dUL] = "Ah, crianças! Vocês chegaram tão longe. Como estou orgulhoso! Vocês realmente são meu maior TRIUNFO científico!",
                    [0xd1b4616f438e655dUL] = "Me sinto... diferente. Mais forte... Que diabos aquele médico maluco fez comigo?",
                    [0xd68a2dffd8d668dbUL] = "Desista, Fritzliebe! Destruímos todos os seus brinquedos!",
                    [0xd8d790471d470c70UL] = "Acabaram os canhões! Os bombardeiros podem passar agora!",
                    [0xdac42869d912eb36UL] = "Uma granada na garganta mata qualquer coisa!",
                    [0xdb8b3082456b7900UL] = "Feche a porta! Isso vai mantê-los fora!",
                    [0xdbf2762283f9e73dUL] = "Não temam! Meu sistema antiaéreo cuidará deles em breve!",
                    [0xdc82a7ffb1baa7ccUL] = "Os bombardeiros não passam por aquele fogo. Não gosto disso... mas vamos ver esses canhões.",
                    [0xe0dc4f2018950395UL] = "Tem um ataque aéreo rolando? Isso pode me dar uma chance...",
                    [0xe1255d1cad20be07UL] = "Argh!!!",
                    [0xe19a4fb2cdb8fac1UL] = "Vai, vai! A porta está aberta!",
                    [0xe1e5058b90f74f7eUL] = "Permita-me me apresentar... Marcel Marie, Resistência Francesa.",
                    [0xe734550562021d44UL] = "Bom estarmos do mesmo lado. Sou o Lt. Eugene McBride, do Exército dos EUA.",
                    [0xe781e161ece2e307UL] = "Temo que nossas chances sejam bem pequenas.",
                    [0xe81aa415f0160f15UL] = "Ainda... esses porões antigos estão em péssimo estado. Raus!!",
                    [0xe924a28306aaa508UL] = "Funcionou! A porta está fechada!",
                    [0xed43510f839db819UL] = "Aí vem!",
                    [0xf0a9d696b19d91f3UL] = "Preciso de uma granada de mão...",
                    [0xf280dd5dda80bf7aUL] = "Sgt. Irina Petrovska, Exército Vermelho.",
                    [0xf499c110f6abe42bUL] = "Vocês são meu maior triunfo... mas também meu maior erro!",
                    [0xf682ec890cd8dea9UL] = "Verdammt! Wo ist der Aufzug?",
                    [0xfb245b1f4cb7b6b8UL] = "...Mais bravo.",
                    [0xfc770e6bb0d4ee7bUL] = "Shh! Achei que ouvi algo...",
                },
                ["ru-RU"] = new()
                {
                    [0x00c828920feb30a9UL] = "Ты не похож на нациста — как ты выжил?",
                    [0x00f894c753526ecaUL] = "Ах, дети мои... вы убили бедного Кригбэра #2.",
                    [0x04ea71f543f7a181UL] = "Но и моя величайшая ОШИБКА! Пора исправить! Фрау штурмбаннфюрер! Приведите их ко мне!",
                    [0x068bd1e0ac21a69eUL] = "Ах да... Нацисты.",
                    [0x130cb8e004b1746fUL] = "O Tannenbaum, o Tannenbaum,\nwie treu sind deine Blätter!",
                    [0x136b271625dfa814UL] = "Нет. Идем дальше. Этот замок еще не мертв.",
                    [0x16c94d4cdbfbd83aUL] = "Нет, нет, нет! Опять опаздываете!",
                    [0x17594f4811a66fb1UL] = "Да... где мы?",
                    [0x18ee39dc7f64b7acUL] = "Символ Шестигранного Солнца... значит, мы в руках ССС.",
                    [0x18fcc16fbb3dd6a8UL] = "Не знаю, но я это выясню.",
                    [0x19e22d8dbc2511f3UL] = "Уничтожь пушки! Граната в ствол справится.",
                    [0x1a5a9e011c4e5fe2UL] = "Лейтенант Юджин Макбрайд, армия США...",
                    [0x1adf386486cd3f55UL] = "Надо уничтожить эти пушки!",
                    [0x1b7ada164ffa40e3UL] = "Это не настоящее имя!",
                    [0x1c07e9eecf9d03ecUL] = "Полагаю, они задумали превратить людей в оружие.",
                    [0x1ffaba68dba5eb7dUL] = "Неважно, потом расскажешь. Мой приказ — вытащить вас отсюда к чертям!",
                    [0x2146921baf773954UL] = "Не знаю, но торчать здесь не буду.",
                    [0x21cbcb67482f6dd3UL] = "Лейтенант Юджин Макбрайд. Американец.",
                    [0x21faa64bab773212UL] = "Я чувствую себя... иначе. Сильнее... крепче.",
                    [0x26229618cf6b2706UL] = "Тихо и спокойно...",
                    [0x263ef99ee3dd3bdfUL] = "(И скоро сам фюрер будет дрожать перед Фрицлибе! Ха-ха!)",
                    [0x266ca9e1237fd940UL] = "Что это, доктор?",
                    [0x29b3a84d1bd5b60fUL] = "Снег... но солнца нет. Снаружи, должно быть, ночь.",
                    [0x29c8a93ca01dfe83UL] = "Да. Помню, как меня схватили... пытали...",
                    [0x2d7f0f37395c44b3UL] = "Ты кто? Немец? Британец?",
                    [0x2e43b75b784acb3aUL] = "Не знаю, но в один из этих баков я не вернусь.",
                    [0x310d3b80502503b9UL] = "Внутрь! Быстро!",
                    [0x33dba133326568c5UL] = "Граната в ствол — то, что надо!",
                    [0x34e13ec981301157UL] = "Теперь вам не пройти, гнилые ублюдки!",
                    [0x3702712331c60bbbUL] = "НЕТ! Не смей трогать рождественскую елку!",
                    [0x37d4da79f91ea69dUL] = "...но у меня есть и много МЕХАНИЧЕСКИХ достижений!",
                    [0x39108d3782fcc184UL] = "Через ЭТО им не пройти!",
                    [0x399d69478283bf0aUL] = "Ах, бедный Кригбэр #2! Он был одним из моих любимцев. Ну ладно... Признаю поражение! Входите, обсудим условия моей капитуляции!",
                    [0x39b11fc2eb9591f7UL] = "Может, подождем здесь? Вдруг нас спасут.",
                    [0x3acef01069bf7698UL] = "Отличная работа! Не знаю, как вы, а я бы укрылся под землей.",
                    [0x3bb78c987c37ef80UL] = "Похоже, они сохранили нашу старую одежду.",
                    [0x3c42fab09bee3aceUL] = "Закрой эту дверь!",
                    [0x3d0b9534cd0767daUL] = "Du grünst nicht nur zur Sommerzeit,\nNein auch im Winter, wenn es schneit!",
                    [0x3d211a9f797e8abcUL] = "Чертов шум! Надо заткнуть эти пушки!",
                    [0x3f1367c4cc04d1ceUL] = "Уррргх... голова моя...",
                    [0x3f57a8067643aaf1UL] = "Покушение!!!",
                    [0x3f7b9829b86ec16dUL] = "Там воздушный налет? Может, это наш шанс сбежать...",
                    [0x421bf0c8717484ceUL] = "Тайное общество внутри Рейха. Секретные исследования — оружие, биоинженерия, оккультизм...",
                    [0x431937b187f1272fUL] = "Это не обычное нацистское знамя. Что это?",
                    [0x455df089e85d4bebUL] = "Осталась одна пушка!",
                    [0x46ee9a6b83e2eaf5UL] = "Снова, с начала! И с большим чувством!",
                    [0x486ff7ab0719fa17UL] = "Спрошу у того ученого, что нас пытал... когда сожму его нацистскую шею!",
                    [0x496af45538186714UL] = "Странно... Я никогда не был бойцом, а теперь чувствую себя неудержимым!",
                    [0x4b729df370265d0aUL] = "Но и моя величайшая ОШИБКА! Пора исправить! Фрау штурмбаннфюрер! Приведите образец!",
                    [0x4babb86958a61d60UL] = "Я тоже чувствую себя в отличной форме...",
                    [0x4bb1cb28780395f0UL] = "Сработало! Осталось две пушки!",
                    [0x4bd699fb74d17592UL] = "Это несправедливо!",
                    [0x4c7ea1bb00311aacUL] = "Надо взорвать их ИЗНУТРИ!",
                    [0x50b1af47c674d007UL] = "Добрый вечер, доктор Фрицлибе! Как продвигается проект Уберкемпфер?",
                    [0x519c7a5ff358e4c4UL] = "Только то, что они нацисты. Худшего сорта.",
                    [0x53192b0aa2e141ffUL] = "Попробуй бросать гранаты ПРЯМО в пушки!",
                    [0x537f76c41d40d6cbUL] = "Боже мой! Остановите их!",
                    [0x5712908027cd5023UL] = "Вы не похожи на нацистов — как вы выжили?",
                    [0x5767d170e5d4e177UL] = "Я сказал, ХАЙЛЬ ГИТЛЕР!",
                    [0x57ed6136f8836ba7UL] = "Второй вентиль! Закрой дверь!",
                    [0x593a7092b87f94baUL] = "Черт! Воздушный налет союзников!",
                    [0x5b1a6ebf6ea7465eUL] = "Превосходно, герр штурмбаннфюрер! Пленники отлично реагируют на формулу. Скоро у фюрера будет непобедимая армия!",
                    [0x5bc1e6c5102e900fUL] = "Видать, им стоило подумать дважды.",
                    [0x5eae866eb3ba9881UL] = "Дверь открыта! Внутрь!",
                    [0x5f9ed0775cd2d462UL] = "Они называют это «Die Sechs-Seitige Sonne». Дурной знак.",
                    [0x612c5f5890b06a4dUL] = "Ааааааа!",
                    [0x6225ce9cb05fbf29UL] = "Что ты знаешь о ССС?",
                    [0x62840e40cb928a25UL] = "Наверное, все дело в тех витаминах, в которых нас купали...",
                    [0x62f96b2e5c9ddd1eUL] = "Нацисты!",
                    [0x6330a806d40f3cdcUL] = "ХНННАРРРР!!!",
                    [0x6361c1d29798d152UL] = "Справедливо. Значит, представляешь, с чем мы столкнулись.",
                    [0x63b1bc586efa968cUL] = "БИОХИМИЯ — моя специальность, это правда...",
                    [0x64edc3775470fac9UL] = "Живым не дамся, черти!",
                    [0x6912caa2276adbb7UL] = "Что это, черт возьми, было!",
                    [0x697cde99d527e9a5UL] = "Что-то эти нацисты почти не сопротивляются, а?",
                    [0x6dc8d99282b85e62UL] = "Я? Мое имя...",
                    [0x6e14c9685d7edd2bUL] = "Надо открыть эту дверь! Тот вентиль подойдет...",
                    [0x6ec71031388eec00UL] = "И как, черт возьми, закрыть эту дверь!",
                    [0x6f47bc553da9b8e5UL] = "*кашляет* Аррргх... Швайнхунде! Вы убили меня... но живыми вы отсюда не уйдете!",
                    [0x6fa7b2bcfe086ad3UL] = "Есть ли путь наверх, на поверхность?",
                    [0x6ff7c93100bf1649UL] = "Я разберу вас и начну заново. В этот раз вы будете идеальны!",
                    [0x700f189385300980UL] = "Граната в ствол должна заткнуть эти пушки...",
                    [0x74e42ee050e494aeUL] = "А ты что, здоровяк? Как тебя звать?",
                    [0x774336bb6f239c56UL] = "Как хочешь.",
                    [0x7853d8633fd979b0UL] = "Попробуй тот красный вентиль!",
                    [0x7c20e94fb4650a48UL] = "Кригбэр #2",
                    [0x7c9ab3548d1d56fdUL] = "Марсель Мари, Французское Сопротивление.",
                    [0x7ec8470fa0f88a10UL] = "Тсс! Слушайте! Что это?",
                    [0x81e08fcf3b26b2c0UL] = "Ах, дитя мое! Ты зашло так далеко. Как я горд! Ты — мой величайший научный ТРИУМФ!",
                    [0x829963066c214aaaUL] = "Д-р Фрицлибе",
                    [0x847689782b9e0876UL] = "Закрой дверь!",
                    [0x88760e3fa2926f3bUL] = "Американец. А ты, дамочка? Русская, верно?",
                    [0x8aee3d0b75a5fd3dUL] = "Вот они!",
                    [0x8b1f68cf084d7b7bUL] = "Открой дверь! Попробуй вентиль!",
                    [0x8c2fe2a554a2db50UL] = "Уррргх...",
                    [0x8ea04a9910d7a8abUL] = "РРРРРРРР!!!",
                    [0x8f2186080cfb3f18UL] = "Что, черт возьми, они со мной сделали? Кажется, я могу поднять грузовик!",
                    [0x8fd83fc67fe9b793UL] = "Ой-ой. Что это за шум?",
                    [0x9401ef9bc24c4cd4UL] = "Берегись!",
                    [0x94d799231e2ef14cUL] = "У кого-нибудь есть граната?",
                    [0x94f3da435499cfefUL] = "Что ты о них знаешь?",
                    [0x99a4111e7666a3b8UL] = "Спрошу у главного ученого, когда сожму его нацистскую шею!",
                    [0x99f616758a5083a7UL] = "Ха! Посмотрим!",
                    [0x99fb968505880e5fUL] = "Это было... жестко. Долго я был без сознания?",
                    [0x9a5fd0af138056fbUL] = "Дверь открыта! Забирайся внутрь!",
                    [0x9e76ca2b1b590009UL] = "Хм! Кригбэр сбежал? Плохой знак для тебя, любимчик!",
                    [0x9f031c4016299ccaUL] = "Если то, что я слышал, правда, вы как раз то, что нужно, чтобы выиграть войну...",
                    [0xa00cfe8c3f89d67eUL] = "Офицер СС",
                    [0xa0af763a31a874f1UL] = "Вот и все, парни. Миссия выполнена.",
                    [0xa13de05f82031646UL] = "Лучше закинуть гранату в ствол.",
                    [0xa31a212dbae8c699UL] = "Пушки... этот чокнутый доктор говорил о какой-то... системе ПВО. Если уничтожить пушки, у бомбардировщиков будет шанс...",
                    [0xa5038973fe6e676fUL] = "Надо пройти через эту дверь! Попробуй вентиль!",
                    [0xa53c1bbac592b0ddUL] = "С чего ты это взял?",
                    [0xa5ddb36f88d25428UL] = "Черт. А я думал, обычных нацистов хватает за глаза.",
                    [0xa8977cac5639d608UL] = "...Стейв Ригур.",
                    [0xa8f097a94f7c134bUL] = "Mon dieu... Что, черт возьми, происходит?",
                    [0xa9f7bfcee3dbb725UL] = "Enchanté, madame. Марсель Мари, Французское Сопротивление.",
                    [0xab049533d0c82bb7UL] = "ХАЙЛЬ ГИТЛЕР!",
                    [0xae93e41c0f96c2f2UL] = "Это было... жестко. Но я пока жив.",
                    [0xafae01eb3b81b195UL] = "Я тоже. Но где мы... Как...?",
                    [0xb20893ef0887644aUL] = "Наглецы!",
                    [0xb42de862d877563fUL] = "Сержант Ирина Петровская. Россия.",
                    [0xb4cad497e51b717eUL] = "Где я, черт возьми...?",
                    [0xb9ceea0299f8a5a8UL] = "Ты хорошо дрался. Я сержант Ирина Петровская.",
                    [0xbb68de4374c81459UL] = "Открой эту дверь! Попробуй вентиль!",
                    [0xbd1c5e1a96342b3dUL] = "Проклятье...",
                    [0xbe70d440b4b5571fUL] = "Умри!",
                    [0xc016c3d70a417178UL] = "Хм! Кригбэр сбежал? Это плохой знак для тебя, мой друг!",
                    [0xc14605f3173c5701UL] = "Скорее, в дверь!",
                    [0xc484c3a4e147841dUL] = "Уничтожь пушки, бросив гранату в ствол!",
                    [0xc7a4c28cb3b0df2eUL] = "Пришло время исправить ошибку! Я разберу вас и начну заново. Следующая модель будет лучше. Она будет ПОВИНОВАТЬСЯ.",
                    [0xcb16811cd0e0063bUL] = "Дверь закрыта! Им не войти!",
                    [0xcc046486f027544dUL] = "Дверь закрыта!",
                    [0xcdd6675c1b199d86UL] = "Кто-то выходит, сэр!",
                    [0xce98a25209ef4e14UL] = "Хор",
                    [0xd087f6ba2b5d6b23UL] = "Пусть летят бомбы! Только бы сначала укрыться под землей...",
                    [0xd1463da2413c9109UL] = "Замок Зонненфройде\nГде-то в Австрии\nДекабрь 1943",
                    [0xd14f14ca876a1d5dUL] = "Ах, дети! Вы зашли так далеко. Как я горд! Вы — мой величайший научный ТРИУМФ!",
                    [0xd1b4616f438e655dUL] = "Я чувствую себя... иначе. Сильнее... Что, черт возьми, этот чокнутый доктор со мной сделал?",
                    [0xd68a2dffd8d668dbUL] = "Сдавайся, Фрицлибе! Мы уничтожили все твои игрушки!",
                    [0xd8d790471d470c70UL] = "Всем пушкам конец! Теперь бомбардировщики пройдут!",
                    [0xdac42869d912eb36UL] = "Ручная граната в глотку убьет что угодно!",
                    [0xdb8b3082456b7900UL] = "Закрой дверь! Это их удержит!",
                    [0xdbf2762283f9e73dUL] = "Не бойтесь! Моя зенитная система скоро с ними разберется!",
                    [0xdc82a7ffb1baa7ccUL] = "Бомбардировщикам через ТАКОЙ огонь не пройти. Не нравится мне это... но займемся этими пушками.",
                    [0xe0dc4f2018950395UL] = "Там воздушный налет? Может, это мой шанс...",
                    [0xe1255d1cad20be07UL] = "Аргх!!!",
                    [0xe19a4fb2cdb8fac1UL] = "Вперед, вперед! Дверь открыта!",
                    [0xe1e5058b90f74f7eUL] = "Позвольте представиться... Марсель Мари, Французское Сопротивление.",
                    [0xe734550562021d44UL] = "Рад, что мы на одной стороне. Я лейтенант Юджин Макбрайд, армия США.",
                    [0xe781e161ece2e307UL] = "Боюсь, наши шансы довольно малы.",
                    [0xe81aa415f0160f15UL] = "И все же... эти старые подвалы в плохом состоянии. Вон!!",
                    [0xe924a28306aaa508UL] = "Сработало! Дверь закрыта!",
                    [0xed43510f839db819UL] = "Ложись!",
                    [0xf0a9d696b19d91f3UL] = "Мне нужна граната...",
                    [0xf280dd5dda80bf7aUL] = "Сержант Ирина Петровская, Красная армия.",
                    [0xf499c110f6abe42bUL] = "Вы — мой величайший триумф... но и моя величайшая ошибка!",
                    [0xf682ec890cd8dea9UL] = "Черт! Где лифт?",
                    [0xfb245b1f4cb7b6b8UL] = "...Злее.",
                    [0xfc770e6bb0d4ee7bUL] = "Тсс! Мне показалось, я что-то слышал...",
                },
            },
            ["52ac9704-61c1-4227-bfd4-9196b81d4f7c"] = new()
            {
                ["es-419"] = new()
                {
                    [0x093b121d9f8d343eUL] = "¡El Equipo Azul gana de nuevo! Pero ¿cuánto les durará la suerte? ¡Sigan atentos!",
                    [0x11142652137306bbUL] = "¡El Equipo Azul muerde el polvo al fin!",
                    [0x19fb0e6fe711f64dUL] = "¡El Equipo Azul es imparable! ¡Ya volvemos!",
                    [0x20702423abf9f849UL] = "¡Damas y caballeros, qué espectáculo! ¡Ya volvemos!",
                    [0x209952c71ddb38e5UL] = "¡Buen trabajo, Equipo Azul! ¡Ya volvemos!",
                    [0x26bed9142b655992UL] = "¡Fantástico! ¡Más del Equipo Azul tras la pausa. ¡No se vayan!",
                    [0x2854a7cd05aae5b4UL] = "¡Guau!",
                    [0x2919a971a06cf7b5UL] = "¡¿Lo vieron, gente en casa?! ¡Increíble!",
                    [0x389c001365ffa7f6UL] = "¡Uf, creí que el Equipo Azul estaba acabado! ¡Quédense, ya volvemos!",
                    [0x578050a4e58e67a7UL] = "¡Se acabó para el Equipo Azul, damas y caballeros!",
                    [0x58f7f09cfc7349b0UL] = "¡De eso se trata! ¡Volvemos tras estos mensajes!",
                    [0x61292c9984cf6c28UL] = "¡Cuidado, Equipo Azul! ¡Peligro, peligro!",
                    [0x63e3b460a0674fcaUL] = "¡El Equipo Azul está que ARDE esta noche! ¡Pero veamos cómo manejan algo de auténtica artillería pesada! Es hora de...",
                    [0x66800b1700467a70UL] = "¡Uf, eso debió doler!",
                    [0x672b08acfa590a83UL] = "¡Damas y caballeros, las cosas se están poniendo intensas aquí en los estudios de SFTV!",
                    [0x79948fe434719e2aUL] = "¡Mala suerte, Equipo Azul! ¡Tuvieron una buena racha!",
                    [0x7a8fd2cd11821d5bUL] = "¡Un final glorioso! ¡Un aplauso para el Equipo Azul, damas y caballeros!",
                    [0x7ee47bf4a237f044UL] = "¡Hermoso! ¡Volveremos con más del Equipo Azul tras la pausa!",
                    [0x8241c4c14185bfffUL] = "¡Buen trabajo! No se vayan, es hora de un descanso.",
                    [0x84bd4babf8ce80b7UL] = "¡Increíble!",
                    [0x8593736b30e839c0UL] = "¡LA ÚLTIMA BATALLA!",
                    [0x902735fb7cf39e65UL] = "¡El Equipo Azul gana de nuevo! ¡Volvemos tras unas palabras de nuestros patrocinadores!",
                    [0xbbfb6ffcd75c6fdcUL] = "¡Ajá! ¡Se acerca un retador!",
                    [0xc841571d4b8013fbUL] = "¡Bum! ¡No toquen ese botón, ya volvemos!",
                    [0xd3fd64b4e4b659d4UL] = "¡Eso sí es entretenimiento! ¡No cambien de canal, ya volvemos!",
                    [0xd52316c473caf2c4UL] = "¡El Equipo Azul vive para pelear otro día! ¡Ya volvemos. ¡Comerciales!",
                    [0xd6d9793046788358UL] = "¡Asombroso!",
                    [0xd6e0acc5ae941713UL] = "Funnyman",
                    [0xd8d0c9b0367bed07UL] = "¡No se vayan, volvemos tras estos mensajes!",
                    [0xd98b22b139b1bad4UL] = "¡Otro que muerde el polvo, damas y caballeros!",
                    [0xdccb17b3660bdff6UL] = "¡Uuuuy, qué feo!",
                    [0xdea8d4b199e2fec9UL] = "¡Eso es todo por esta noche! ¡Un aplauso una vez más para el Equipo Azul!",
                    [0xebfe1f0c1efdf566UL] = "¡El Equipo Azul no decepciona! ¡Quédense, ya volvemos!",
