                    [0x01051dfa0e811b17UL] = "Вас понял, альфа 3. Все отряды выдвинуты, приближаемся к цели.",
                    [0x01d074f6960b333eUL] = "Чувствуешь дезориентацию? Не волнуйся!",
                    [0x03975ae59704af11UL] = "Три!",
                    [0x1263fd91b03b820dUL] = "Настало время, дамы и господа, долгожданного финала сезона Супербойцы Live!",
                    [0x159daaac4f56d7e3UL] = "Я НЕ вернусь в Детский Час!!!",
                    [0x18bb1c8f44f2b01dUL] = "Помни — либо они, либо мы!",
                    [0x1a24dee897c52d65UL] = "Стоп пресса!",
                    [0x1f08e947dd01d281UL] = "Хи хи!",
                    [0x21ca3b0f1921b2f0UL] = "Вы не можете так с нами!",
                    [0x23f457d3dc9522ebUL] = "Два!",
                    [0x2548fccef3d6e3f0UL] = "Отлично сработано! Ты разделался с этими панками!",
                    [0x2a75dd56ca6fef83UL] = "Хе хе хе...",
                    [0x2b030ca41081902aUL] = "Весельчак",
                    [0x305903dfa72e5681UL] = "Аминь.",
                    [0x3228cdb77e06939eUL] = "Отлично! Но теперь начинается настоящий бой!",
                    [0x403edcea71ed28f2UL] = "Пусть бой начнется!",
                    [0x40520bc2d689e8bfUL] = "Я на это не подписывался!",
                    [0x40bacd1373b04133UL] = "Тень",
                    [0x421cdc4d883c8583UL] = "По нам попали!",
                    [0x4246cde8955c0d0aUL] = "Что вы задумали, а? Даже если уничтожите шоу, вам не взорвать всю студию!",
                    [0x466826e5b94c6438UL] = "Какого черта! КАКОГО ЧЕРТА!",
                    [0x4833e9b1cf715897UL] = "Это так, мешок с мясом?",
                    [0x49c11f74d2d221b6UL] = "Вертолет должен быть уничтожен!",
                    [0x548033483ff07773UL] = "Подъем, супербойцы! За работу!",
                    [0x55149a4460de4b70UL] = "...и помните: ВЕСЕЛИТЕСЬ!",
                    [0x558b436a14b705f3UL] = "Давай! Шоу начинается, а ты — звезда.",
                    [0x57baa73f374e4b28UL] = "Звезда!\nХи хи!",
                    [0x585ea9637c40eb85UL] = "Ох — все критики...",
                    [0x590434a5c8266949UL] = "Но представь, что кто-то обрушит вещательную башню. Что кто-то остановит сигнал...",
                    [0x593733f7399f7e59UL] = "Становится поздно.",
                    [0x5e527bdbd65a1c2aUL] = "У меня отличная карьера, и я не дам каким-то био-мутантам все испортить!",
                    [0x5e5bdfb945b89585UL] = "Уверен, ты понимаешь, что не выйдешь из этого здания. Все выходы отрезаны, идет подкрепление.",
                    [0x6912caa2276adbb7UL] = "Что это, черт, было?!",
                    [0x6aae9fd4dc8010c2UL] = "Давай! Публика не кусается! Хе хе!",
                    [0x6ea9fdd66ed01b03UL] = "Проваливай, малец!",
                    [0x6f6f696a6fd2bd8eUL] = "Какая команда победит в Яме? Сейчас узнаем!",
                    [0x70a710fe93868301UL] = "Просто расслабься и делай, что естественно.",
                    [0x716d631bdc4e252fUL] = "Вот это драка! Дамы и господа —",
                    [0x726248305e62397dUL] = "Семь, восемь!",
                    [0x737ebf3c0d67cbd4UL] = "Надеюсь, ради твоего блага, ты... ОБЕСПЕЧИШЬ тела. Многие хотели бы заполучить эти образцы.",
                    [0x745524d8e00450beUL] = "Давай, мешки с мясом! Шоу начинается!",
                    [0x759cb1960641dd4bUL] = "Тела?",
                    [0x76590b86f59c73cbUL] = "Слушай, умник, последнее предупреждение! Сейчас считаю до десяти, и лучше бы тебе свалить!",
                    [0x7cb05c036d2c4aa9UL] = "Один!",
                    [0x82201369d24c01faUL] = "Готово!\nХи хи!",
                    [0x847673fe434aab35UL] = "Убейте их всех!",
                    [0x857671edfdba06d4UL] = "Ты был ЗВЕЗДОЙ! Ты давал людям то, что они хотели! Без этого кто ты? Просто сломанные игрушечные солдатики!",
                    [0x8593736b30e839c0UL] = "...ПОСЛЕДНЕЙ БИТВЫ!",
                    [0x8d30cbd182017c10UL] = "Еще 23 убийства и у меня свое кулинарное шоу!",
                    [0x8df489f87cc6a52cUL] = "Сейчас починю!",
                    [0x8e5f0f7f5c0cbb8aUL] = "Вам конец, супербойцы! Вы больше не будете работать в этом городе!",
                    [0x8f1e57d77f5fb234UL] = "Срочно! Студия ТВ в руинах! Любимец публики предположительно погиб! Шоу №1 закрыто на неопределенный срок! Читайте в Sunny City Times!",
                    [0x90f99afdd0b387b5UL] = "Арргх!",
                    [0x94371d46ab899fceUL] = "Идиоты! Если бы это стекло не было совершенно неразбиваемым...",
                    [0x96cfa4c69e8d418dUL] = "...СУПЕРБОЙЦОВ!",
                    [0x97ba63e54f080fd7UL] = "Чего...!?",
                    [0x97c9b369d808ee00UL] = "Боязнь сцены!\nХи хи!",
                    [0x9d225ae156a9deb8UL] = "Пилот",
                    [0x9ed352df60c04af4UL] = "Три!\nХи!",
                    [0xa298bb2dba5188a6UL] = "Ого!",
                    [0xac82644893598f19UL] = "Не обнаружены, сэр. Башня рухнула на три квартала. Отряды уже в пути. Полный бардак, сэр.",
                    [0xaca9b9d39992fc48UL] = "ДЕСЯТЬ!",
                    [0xad1436378a5175c9UL] = "Эй вы, супербойцы — почему вы не играете по правилам?",
                    [0xae134444f7c26076UL] = "Шоу!\nХи хи!",
                    [0xb483ac5f4a34476eUL] = "Эй, это все часть шоу, друзья! Мы вернемся сразу после рекламы!",
                    [0xb78b4049d2165930UL] = "Вы не понимаете, мы несем службу обществу! Поддерживаем порядок! Без Супербойцов был бы ХАОС!",
                    [0xb81f65f163aea663UL] = "Отличная работа! Передохни перед следующим испытанием.",
                    [0xc15f97b9f9a0bf19UL] = "Пять!",
                    [0xc1956c95db4f1635UL] = "Не кусается!\nХи хи!",
                    [0xc285478a7ef5c1ddUL] = "Экстренно! Новые подробности! Преступники могут быть еще на свободе! Розыск начался в...",
                    [0xc4344d31c649a69aUL] = "Невероятно! Команда Синих все еще на ногах! Дадим еще жару!",
                    [0xc5a3ed4ef701c31bUL] = "Идти некуда, кроме как вверх.",
                    [0xc8814e7e4c55afbdUL] = "Динамик",
                    [0xc8b4fbbda23d60d2UL] = "Дамы и господа, поприветствуйте на сцене...",
                    [0xc8c63ccd03e9ac5cUL] = "Весь город сходит с ума. И будет хуже. Чувствую.",
                    [0xcad5dabf8a1ecadcUL] = "Эм... босс?",
                    [0xcf8171b349c00823UL] = "ХИ ХИ ХИ!",
                    [0xd04ab4fb2986fad5UL] = "А теперь пора заслуженно отдохнуть. Сладких снов!",
                    [0xd0b4e6c8d948c128UL] = "Охрана! ОСТАНОВИТЕ ИХ!",
                    [0xd107308732c7068dUL] = "Убив меня, ничего не изменишь! Я лишь ширма... человек в дорогом костюме. Меня заменят... но я этого не допущу!",
                    [0xd1a5c5ce237089abUL] = "Ну что, займемся чем-нибудь потом?",
                    [0xd25289172c636d65UL] = "Команда Синих побеждает!",
                    [0xd4bc894a27001cf2UL] = "Оооо.\n...Да, пожалуй.",
                    [0xd6e0acc5ae941713UL] = "Весельчак",
                    [0xd7ae1a2beb4b3228UL] = "В этот раз без охотников — лишь элита: накачанные, свихнувшиеся супербойцы прямо из пробирок!",
                    [0xd8a2da16e9c7b997UL] = "Вы... еще... не победили!...",
                    [0xd9ce7ca456113fb7UL] = "А теперь посмотрим, как они справятся с настоящим огнем! Пора...",
                    [0xda4c2730e89389e5UL] = "Вот — добейте их!",
                    [0xe0b85b403f25d327UL] = "Не в ЭТОМ смысле, сержант.",
                    [0xe13045c4ba53f183UL] = "Занавес... падает...",
                    [0xe51e11442202a632UL] = "Где-то в Санни-Сити\n20XX",
                    [0xe8d08ca0c960add4UL] = "Идет подкрепление. Тебе лучше двигаться дальше.",
                    [0xea7831fb17de8c48UL] = "Твое время на исходе. Они идут.",
                    [0xeee6f11d36af4eccUL] = "Не хочешь закончить как эти бедолаги. Видимо, боязнь сцены, хе хе!",
                    [0xef6bff69b221b98dUL] = "Что будут делать люди, интересно, без своего драгоценного развлечения?",
                    [0xefe036c18f965932UL] = "На этом все, друзья! НО не забудьте завтра — тогда начнется НАСТОЯЩАЯ драка.",
                    [0xf231e5083f325b35UL] = "Неблагодарные свиньи! Что бы вы без нас делали?",
                    [0xf34bbac8ee388f22UL] = "Это БОЛЬНО! Я с удовольствием убью тебя!",
                    [0xf4f217f8d4781209UL] = "Девять!",
                    [0xf838cce5cc35ccdeUL] = "Есть над чем подумать, полагаю.",
                    [0xf84fcce272aa881dUL] = "Черт!",
                    [0xfb2d0576fdf4511fUL] = "Тяжелая ночка, а?",
                    [0xfc2d3c1ce47a805eUL] = "Отходим!",
                    [0xfdceebfbb5ed9ec2UL] = "Идет подкрепление! Вы в ловушке! Лучше сдавайтесь!",
                    [0xfe9e91d49ea5398fUL] = "Твоя остановка.",
                },
            },
            ["a4244c9d-2ef2-40d7-acb2-dcf1579b5056"] = new()
            {
                ["es-419"] = new()
                {
                    [0x355f12fe77de5784UL] = "¡Esto no ha terminado, policías! ¡Ustedes ya son historia! ¡MetroLaw es el futuro!",
                    [0x417cd86cc0ca6c17UL] = "De lo contrario, se les cobrará en su totalidad cualquier daño adicional a edificios de importancia cultural durante su arresto...",
                    [0x425ee91164382a0aUL] = "Sus hombres deberían aprender a no apuntar con sus armas a un compañero de la ley. Somos los detectives McBride y Santana, del SCPD. A partir de ahora, esto es asunto nuestro.",
                    [0x466aae9dccce80d5UL] = "Ah, pero esto sigue siendo jurisdicción de la SCPD. Lo siento, oficial. Si quiere su premio, tendrá que seguir los trámites correspondientes.",
                    [0x8050359da2050ad6UL] = "Ayúdame a esposarlos, Santana. Nos vamos a la central.",
                    [0x8422c9c595e7687cUL] = "¡P-pero QUÉ!",
                    [0xa42e1ea0d7d127c8UL] = "Muy bien, muchachos, esposen a estos sacos de carne rápido antes de que despierten.",
                    [0xb9158363e1220395UL] = "¡Lárguense, aficionados! Estos son los sacos de carne que volaron la estación de televisión. Son propiedad del gobierno.",
                    [0xc1e47df7de9703a5UL] = "Al resistirse al arresto, aceptan los términos y condiciones tal como los he presentado. De acuerdo, sargento, puede proceder con el arresto.",
                    [0xc8814e7e4c55afbdUL] = "Voz del Altavoz",
                    [0xddc4eae441a43c65UL] = "Estoy empezando a creer que el comisionado tiene razón... ¡Eres un cañón suelto, Johnny!",
                    [0xe14aefb8dc626bcbUL] = "¡Atención, superluchadores! ¡Están rodeados! Ríndanse ahora y recibirán el cuidado profesional galardonado de MetroLaw...",
                },
