                    [0xc8814e7e4c55afbdUL] = "Alto-falante",
                    [0xddc4eae441a43c65UL] = "Começo a achar que o comissário tem razão... Você é descontrolado, Johnny!",
                    [0xe14aefb8dc626bcbUL] = "Atenção, superlutadores! Vocês estão cercados! Rendam-se agora e receberão o premiado cuidado profissional da MetroLaw...",
                },
                ["ru-RU"] = new()
                {
                    [0x355f12fe77de5784UL] = "Это еще не конец, легавые! Вам конец! Будущее за MetroLaw!",
                    [0x417cd86cc0ca6c17UL] = "В противном случае с вас в полном объеме взыщут ущерб за любые дальнейшие повреждения культурно значимых зданий при задержании...",
                    [0x425ee91164382a0aUL] = "Вашим людям стоит научиться не направлять пушки на fellow офицера. Мы детективы Макбрайд и Сантана, SCPD. Дальше мы сами.",
                    [0x466aae9dccce80d5UL] = "Но это все еще участок SCPD. Извините, офицер. Если хотите свой приз, идите по всем инстанциям.",
                    [0x8050359da2050ad6UL] = "Помоги их заковать, Сантана. Едем в участок.",
                    [0x8422c9c595e7687cUL] = "Ч-что?!",
                    [0xa42e1ea0d7d127c8UL] = "Ладно, парни, быстро наденьте наручники на эти мешки с мясом, пока не очнулись.",
                    [0xb9158363e1220395UL] = "Проваливайте, мелюзга! Эти мешки с мясом взорвали телестанцию. Они — собственность правительства.",
                    [0xc1e47df7de9703a5UL] = "Оказывая сопротивление аресту, вы принимаете мои условия, как я их изложил. Ладно, сержант, приступайте к задержанию.",
                    [0xc8814e7e4c55afbdUL] = "Динамик",
                    [0xddc4eae441a43c65UL] = "Начинаю думать, что комиссар прав... Ты неуправляемый, Джонни!",
                    [0xe14aefb8dc626bcbUL] = "Внимание, супербойцы! Вы окружены! Сдавайтесь сейчас, и получите фирменный первоклассный уход от MetroLaw...",
                },
            },
